/* ================= FISICA PLUS 2 · orientata alle prove 2025 =================
   Porta ogni argomento ad almeno 22 domande insistendo sui tipi più frequenti nelle prove di Fisica
   del semestre filtro 2025 (Archimede con carico, Stevino con pressione assoluta, decibel, Doppler in %,
   isobara e segno del lavoro, conversioni di velocità/accelerazione/volumi, Poiseuille, V = Q/C, lenti)
   e sugli errori tipici. Aggiunge un esempio svolto e un paragrafo «Come si ragiona negli esercizi:»
   per ogni argomento. Caricato dopo b12_fisica_plus.js. */

FIS_QB.push(
{t:"u1a",k:"m",q:"Quante sono le grandezze fondamentali del Sistema Internazionale?",o:["4","7","5","6","9"],a:1,s:"Lunghezza, massa, tempo, corrente, temperatura, quantità di sostanza, intensità luminosa: sette, con le unità m, kg, s, A, K, mol, cd."},
{t:"u1a",k:"m",q:"Il prefisso «mega» (M) corrisponde al fattore:",o:["10³","10⁹","10⁻⁶","10¹²","10⁶"],a:4,s:"kilo = 10³, mega = 10⁶, giga = 10⁹. Non confondere M (mega, 10⁶) con m (milli, 10⁻³)."},
{t:"u1a",k:"c",q:"Il prefisso «nano» (n) corrisponde al fattore 10 elevato alla ____ .",a:["-9","−9","MENO 9"],s:"milli 10⁻³, micro 10⁻⁶, nano 10⁻⁹, pico 10⁻¹²."},
{t:"u1a",k:"m",q:"Quale coppia è formata, nell'ordine, da una grandezza intensiva e da una estensiva?",o:["massa e volume","volume e densità","pressione e volume","energia e temperatura","carica e massa"],a:2,s:"La pressione non cambia se si prende metà del sistema (intensiva), il volume sì (estensiva)."},
{t:"u1a",k:"m",q:"La candela è l'unità fondamentale del SI per:",o:["l'intensità luminosa","la potenza irradiata","il flusso magnetico","la quantità di carica","la frequenza"],a:0,s:"È la settima unità fondamentale; la potenza si misura in watt (derivata), il flusso magnetico in weber, la carica in coulomb."},
{t:"u1a",k:"c",q:"Una grandezza che non cambia dividendo un sistema omogeneo a metà, come la pressione o la temperatura, si dice ____ .",a:["INTENSIVA"],s:"Le intensive non dipendono dalla quantità di materia; le estensive (massa, volume, energia) sì."},
{t:"u1b",k:"c",q:"Un'auto aumenta la velocità di 36 km/h ogni secondo: la sua accelerazione vale ____ m/s².",a:["10","DIECI"],s:"36 km/h = 36/3,6 = 10 m/s; aumentare di 10 m/s ogni secondo significa a = 10 m/s². Errore tipico del 2025: dimenticare di convertire i km/h prima di dividere per il tempo."},
{t:"u1b",k:"m",q:"La densità di un legno è 600 kg/m³. Espressa in g/cm³ vale:",o:["600","60","6","0,6","0,06"],a:3,s:"1 g/cm³ = 1000 kg/m³, quindi 600 kg/m³ = 0,6 g/cm³. Attenzione: «kg/cm³» sarebbe un'unità sbagliata di un fattore 10⁶."},
{t:"u1b",k:"m",q:"Un flacone contiene 250 mL di soluzione. Il volume in m³ è:",o:["2,5·10⁻¹ m³","2,5·10⁻⁴ m³","2,5·10⁻² m³","2,5·10⁻⁶ m³","2,5·10⁻³ m³"],a:1,s:"250 mL = 0,25 L = 0,25 dm³ = 0,25·10⁻³ m³ = 2,5·10⁻⁴ m³ (1 L = 1 dm³ = 10⁻³ m³)."},
{t:"u1b",k:"c",q:"Con 1 atm ≈ 10⁵ Pa, una pressione assoluta di 2,5 atm vale ____ kPa.",a:["250"],s:"2,5·10⁵ Pa = 250·10³ Pa = 250 kPa."},
{t:"u1c",k:"m",q:"Un vettore ha componenti (6; 8). Il suo modulo è:",o:["14","48","2","100","10"],a:4,s:"Teorema di Pitagora: √(6² + 8²) = √100 = 10. Sommare le componenti (14) è l'errore tipico."},
{t:"u1c",k:"c",q:"Due forze di 5 N, una diretta verso est e una verso nord, agiscono su un punto: la risultante forma con la direzione est un angolo di ____ gradi.",a:["45","QUARANTACINQUE"],s:"Componenti uguali → tan θ = 5/5 = 1 → θ = 45°."},
{t:"u1c",k:"m",q:"Quanto vale tan 45°?",o:["0","0,5","1","0,71","infinito"],a:2,s:"tan 45° = sin 45°/cos 45° = 1, perché seno e coseno sono uguali."},
{t:"u1c",k:"m",q:"Due vettori di modulo 3 e 4 formano un angolo di 120°. Il loro prodotto scalare vale:",o:["−6","6","12","−12","0"],a:0,s:"a·b = |a||b|cos 120° = 3·4·(−0,5) = −6: il prodotto scalare è negativo quando l'angolo è ottuso."},
{t:"u1d",k:"m",q:"Quale grandezza ha dimensioni [M][L]²[T]⁻³?",o:["energia","forza","pressione","potenza","quantità di moto"],a:3,s:"Potenza = energia/tempo = [M][L]²[T]⁻² / [T]."},
{t:"u1d",k:"c",q:"La costante elastica k di una molla (F = k·x) ha dimensioni [M][T]^x: l'esponente x vale ____ .",a:["-2","−2","MENO 2"],s:"k = F/x = N/m = (kg·m/s²)/m = kg/s² → [M][T]⁻²."},
{t:"u1d",k:"m",q:"Quale delle seguenti grandezze NON è adimensionale?",o:["indice di rifrazione","viscosità","rendimento","coefficiente di attrito","densità relativa"],a:1,s:"La viscosità si misura in Pa·s; le altre sono rapporti tra grandezze omogenee."},
{t:"u1d",k:"m",q:"Il periodo di un pendolo dipende dalla lunghezza l e da g. Quale combinazione ha le dimensioni di un tempo?",o:["√(l·g)","l/g","g/l","l·g","√(l/g)"],a:4,s:"[l/g] = m/(m/s²) = s², la radice dà secondi. √(l·g) è invece una velocità."},
{t:"u1d",k:"c",q:"Un angolo misurato in radianti è il rapporto tra un arco e un raggio: è quindi una grandezza ____ .",a:["ADIMENSIONALE"],s:"Lunghezza diviso lunghezza: il radiante è un numero puro."},
{t:"u1d",k:"m",q:"In una formula come N = N₀·e^(−λt), l'esponente λt deve essere:",o:["un tempo","una frequenza","adimensionale","una lunghezza","un'energia"],a:2,s:"Gli argomenti di esponenziali, logaritmi e seni sono numeri puri; quindi λ si misura in s⁻¹."},
{t:"u2a",k:"m",q:"Un'auto viaggia a 90 km/h. Quanta strada percorre in 4 s?",o:["100 m","360 m","25 m","22,5 m","1000 m"],a:0,s:"90 km/h = 25 m/s; s = v·t = 25·4 = 100 m. 360 m nasce dal non convertire i km/h."},
{t:"u2a",k:"c",q:"Un'auto passa da ferma a 108 km/h in 10 s: l'accelerazione media è ____ m/s².",a:["3","TRE"],s:"108 km/h = 30 m/s; a = Δv/Δt = 30/10 = 3 m/s²."},
{t:"u2a",k:"m",q:"Un ciclista percorre metà del tragitto a 10 km/h e l'altra metà, della stessa lunghezza, a 30 km/h. La velocità media è:",o:["20 km/h","25 km/h","17,5 km/h","15 km/h","10 km/h"],a:3,s:"Con tratti di 30 km: tempi 3 h + 1 h = 4 h per 60 km → 15 km/h. La media aritmetica (20) è sbagliata perché i tempi sono diversi."},
{t:"u2a",k:"m",q:"Nel grafico velocità-tempo di un corpo c'è una retta inclinata verso il basso che taglia l'asse dei tempi. Il corpo:",o:["accelera sempre nello stesso verso","rallenta, si ferma e poi si muove in verso opposto","è fermo","si muove di moto uniforme","ha accelerazione che cresce nel tempo"],a:1,s:"La pendenza costante negativa è l'accelerazione; dove v cambia segno il corpo inverte il verso."},
{t:"u2a",k:"c",q:"Un sasso lanciato verso l'alto a 15 m/s (g = 10 m/s²) raggiunge il punto più alto dopo ____ s.",a:["1,5","1.5"],s:"In cima v = 0: t = v₀/g = 15/10 = 1,5 s."},
{t:"u2a",k:"m",q:"Due auto partono insieme dallo stesso punto: A a velocità costante di 20 m/s, B da ferma con accelerazione 4 m/s². Dopo quanto tempo B raggiunge A?",o:["5 s","20 s","2,5 s","40 s","10 s"],a:4,s:"20t = ½·4·t² → t = 10 s. A 5 s B ha solo la stessa velocità di A, non lo stesso spazio."},
{t:"u2b",k:"m",q:"Un punto ruota su una circonferenza di raggio 0,5 m compiendo 2 giri al secondo. La sua velocità è circa:",o:["1 m/s","3,1 m/s","6,3 m/s","12,6 m/s","2 m/s"],a:2,s:"v = 2πr·f = 2·3,14·0,5·2 ≈ 6,3 m/s."},
{t:"u2b",k:"c",q:"In un moto circolare uniforme di raggio 2 m con velocità angolare 3 rad/s la velocità vale ____ m/s.",a:["6","SEI"],s:"v = ω·r = 3·2 = 6 m/s."},
{t:"u2b",k:"m",q:"Un proiettile è lanciato orizzontalmente. Raddoppiando la velocità di lancio, a parità di altezza, il tempo di volo:",o:["resta uguale","raddoppia","si dimezza","quadruplica","dipende dalla massa"],a:0,s:"Il moto verticale è una caduta libera indipendente da quello orizzontale: raddoppia solo la gittata."},
{t:"u2b",k:"m",q:"Dal bordo di un tavolo si lancia orizzontalmente una pallina e nello stesso istante se ne lascia cadere un'altra dalla stessa altezza. Trascurando l'aria:",o:["arriva prima quella lanciata","arriva prima quella lasciata cadere","arriva prima la più pesante","toccano terra nello stesso istante","dipende dalla velocità di lancio"],a:3,s:"Hanno la stessa velocità verticale iniziale (zero) e la stessa accelerazione g."},
{t:"u2b",k:"c",q:"Un proiettile è lanciato a 30 m/s con un angolo di 30° sull'orizzontale: la componente orizzontale della velocità vale circa ____ m/s (cos 30° ≈ 0,87).",a:["26","26,1","26.1"],s:"vₓ = v·cos 30° ≈ 30·0,87 ≈ 26 m/s, e resta costante per tutto il volo."},
{t:"u2b",k:"m",q:"In una centrifuga si raddoppia il raggio a parità di velocità angolare. L'accelerazione centripeta (a = ω²r):",o:["si dimezza","raddoppia","quadruplica","resta uguale","diventa un quarto"],a:1,s:"A ω costante a è proporzionale a r. Il «quadruplica» vale invece raddoppiando v (a = v²/r)."},
{t:"u2c",k:"m",q:"Un corpo di 2 kg è su un piano inclinato liscio di 30° (g = 10 m/s²). La componente del peso parallela al piano vale:",o:["20 N","17 N","5 N","0 N","10 N"],a:4,s:"P∥ = mg·sin 30° = 20·0,5 = 10 N. 17 N è la componente perpendicolare (mg·cos 30°)."},
{t:"u2c",k:"m",q:"Sullo stesso piano inclinato liscio di 30°, con il corpo di 2 kg (g = 10 m/s²), la reazione normale vale circa:",o:["20 N","10 N","17 N","34 N","0 N"],a:2,s:"N bilancia la componente perpendicolare del peso: mg·cos 30° ≈ 20·0,87 ≈ 17 N. Non è mg."},
{t:"u2c",k:"c",q:"Una persona di 60 kg sta su una bilancia in un ascensore che accelera verso l'alto a 2 m/s² (g = 10 m/s²): la bilancia segna una forza di ____ N.",a:["720"],s:"N − mg = ma → N = m(g + a) = 60·12 = 720 N."},
{t:"u2c",k:"m",q:"Due blocchi di 3 kg e 2 kg sono a contatto su un piano liscio; una forza orizzontale di 10 N spinge il blocco da 3 kg. La forza che il primo blocco esercita sul secondo è:",o:["4 N","10 N","6 N","5 N","2 N"],a:0,s:"a = 10/5 = 2 m/s²; il blocco da 2 kg è spinto solo dal primo: F = 2·2 = 4 N."},
{t:"u2c",k:"c",q:"Una molla si allunga di 4 cm quando vi si appende una massa di 200 g (g = 10 m/s²): la costante elastica è ____ N/m.",a:["50","CINQUANTA"],s:"k = mg/x = (0,2·10)/0,04 = 50 N/m. Errore tipico: lasciare grammi e centimetri."},
{t:"u2c",k:"m",q:"Un corpo lanciato verso l'alto, nel punto più alto della traiettoria verticale, ha:",o:["velocità nulla e accelerazione nulla","velocità massima","accelerazione verso l'alto","velocità nulla e accelerazione g verso il basso","forza risultante nulla"],a:3,s:"Il peso agisce sempre: la forza risultante è mg anche quando il corpo è fermo per un istante."},
{t:"u2d",k:"m",q:"Una forza F = (3; 4) N sposta un corpo di s = (2; 1) m. Il lavoro compiuto è:",o:["14 J","10 J","25 J","5 J","7 J"],a:1,s:"Prodotto scalare con le componenti: L = 3·2 + 4·1 = 10 J."},
{t:"u2d",k:"c",q:"Si trascina una valigia per 10 m tirando con 50 N una maniglia inclinata di 60° rispetto al pavimento: il lavoro della forza è ____ J.",a:["250"],s:"L = F·s·cos 60° = 50·10·0,5 = 250 J: conta solo la componente parallela allo spostamento."},
{t:"u2d",k:"m",q:"Un corpo di 1 kg scivola su un piano orizzontale a 4 m/s e si ferma per attrito. Il lavoro della forza d'attrito è:",o:["+8 J","−16 J","0 J","+4 J","−8 J"],a:4,s:"Teorema dell'energia cinetica: L = ΔK = 0 − ½·1·16 = −8 J. È negativo perché l'attrito si oppone al moto."},
{t:"u2d",k:"m",q:"Una pompa solleva 600 kg d'acqua di 5 m in un minuto (g = 10 m/s²). La potenza minima è:",o:["50 W","3000 W","500 W","30 kW","5 kW"],a:2,s:"L = mgh = 30 000 J; P = L/t = 30 000/60 = 500 W. 30 kW nasce dal non convertire il minuto in secondi."},
{t:"u2d",k:"c",q:"Un'auto di 1000 kg passa da 10 m/s a 20 m/s: il lavoro totale compiuto sull'auto è ____ kJ.",a:["150"],s:"L = ½m(v₂² − v₁²) = 500·(400 − 100) = 150 000 J. Non ½m(Δv)² = 50 kJ."},
{t:"u2d",k:"m",q:"Un sasso di 0,5 kg cade da 10 m e arriva a terra a 12 m/s (g = 10 m/s²). L'energia dissipata dalla resistenza dell'aria è:",o:["14 J","36 J","50 J","86 J","0 J"],a:0,s:"Energia iniziale mgh = 50 J; finale ½·0,5·144 = 36 J; la differenza, 14 J, è stata dissipata."},
{t:"u2e",k:"m",q:"Un'asta leggera orizzontale, imperniata a un estremo, regge a 2 m dal perno un peso di 30 N. Il momento rispetto al perno è:",o:["15 N·m","30 N·m","120 N·m","60 N·m","0 N·m"],a:3,s:"M = F·b = 30·2 = 60 N·m (forza perpendicolare al braccio)."},
{t:"u2e",k:"c",q:"Su un'altalena a bilico un bambino di 30 kg siede a 2 m dal fulcro: per l'equilibrio, un bambino di 40 kg deve sedersi dall'altra parte a ____ m.",a:["1,5","1.5"],s:"30·2 = 40·x → x = 1,5 m: il più pesante sta più vicino al fulcro."},
{t:"u2e",k:"m",q:"Due masse di 3 kg e 1 kg sono agli estremi di un'asta leggera lunga 4 m. Il centro di massa dista dalla massa di 3 kg:",o:["3 m","1 m","2 m","0,75 m","1,33 m"],a:1,s:"Origine sulla massa da 3 kg: x = (3·0 + 1·4)/4 = 1 m; il CM è più vicino alla massa maggiore."},
{t:"u2e",k:"m",q:"Le forbici e la bilancia a bracci uguali sono leve di:",o:["2° genere","3° genere","2° genere se vantaggiose","nessun genere","1° genere"],a:4,s:"Il fulcro sta tra la forza motrice e la resistenza: primo genere."},
{t:"u2e",k:"c",q:"In una leva il braccio della forza motrice è il triplo di quello della resistenza: il vantaggio meccanico (resistenza/forza) vale ____ .",a:["3","TRE"],s:"F·3b = R·b → R/F = 3: la leva è vantaggiosa."},
{t:"u2f",k:"m",q:"Due carrelli di 1 kg si muovono uno verso l'altro a 2 m/s ciascuno, si urtano e restano attaccati. Dopo l'urto:",o:["vanno a 2 m/s","vanno a 1 m/s","sono fermi","vanno a 4 m/s","rimbalzano a 2 m/s"],a:2,s:"Quantità di moto totale: 1·2 + 1·(−2) = 0, quindi dopo l'urto v = 0. L'energia cinetica è tutta dissipata."},
{t:"u2f",k:"c",q:"Un carrello di 3 kg a 4 m/s urta e si aggancia a un carrello fermo di 1 kg: l'energia cinetica persa nell'urto è ____ J.",a:["6","SEI"],s:"v' = 12/4 = 3 m/s; K prima = ½·3·16 = 24 J, dopo = ½·4·9 = 18 J; persi 6 J."},
{t:"u2f",k:"m",q:"Una palla di 0,5 kg urta un muro a 6 m/s e rimbalza indietro a 4 m/s; il contatto dura 0,1 s. La forza media del muro sulla palla è:",o:["50 N","10 N","20 N","5 N","100 N"],a:0,s:"Δp = 0,5·(4 − (−6)) = 5 kg·m/s; F = Δp/Δt = 50 N. Sottrarre le velocità (6 − 4) dimentica il cambio di verso."},
{t:"u2f",k:"m",q:"Il grafico forza-tempo di un urto è un triangolo con base 0,2 s e altezza 100 N. L'impulso è:",o:["20 N·s","100 N·s","5 N·s","10 N·s","500 N·s"],a:3,s:"L'impulso è l'area sotto F(t): ½·0,2·100 = 10 N·s."},
{t:"u2f",k:"c",q:"Un nucleo fermo di massa 4m si spezza in due frammenti di massa 3m e m. Se il frammento leggero parte a 9·10⁵ m/s, quello pesante parte in verso opposto a ____ ·10⁵ m/s.",a:["3","TRE"],s:"p totale nulla: m·9·10⁵ = 3m·v → v = 3·10⁵ m/s."},
{t:"u2f",k:"m",q:"In un urto completamente anelastico tra due corpi, l'energia cinetica totale:",o:["si conserva sempre","diminuisce, perché in parte diventa calore e deformazione","aumenta","raddoppia","si annulla sempre"],a:1,s:"Si conserva la quantità di moto, non l'energia cinetica; si annulla solo se la quantità di moto totale è nulla."},
{t:"u3a",k:"c",q:"Un sub è a 30 m di profondità in mare (ρ ≈ 1000 kg/m³, g = 10 m/s², pressione atmosferica ≈ 10⁵ Pa): la pressione assoluta è ____ atm.",a:["4","QUATTRO"],s:"ρgh = 3·10⁵ Pa (3 atm) più 1 atm di pressione atmosferica = 4 atm."},
{t:"u3a",k:"m",q:"Uno studente calcola la pressione a 20 m di profondità in acqua come p = ρgh = 2·10⁵ Pa. Che cosa ha trascurato?",o:["la densità dell'aria","la spinta di Archimede","la temperatura dell'acqua","nulla, il calcolo è completo","la pressione atmosferica: quella assoluta è circa 3·10⁵ Pa"],a:4,s:"ρgh è la pressione relativa; quella assoluta aggiunge la pressione atmosferica sulla superficie (Stevino: p = p₀ + ρgh). È l'errore più frequente."},
{t:"u3a",k:"m",q:"Una flebo è appesa 1 m sopra il braccio del paziente (ρ ≈ 1000 kg/m³, g = 10 m/s²). La pressione idrostatica della soluzione all'ago è circa:",o:["10² Pa","10³ Pa","10⁴ Pa","10⁵ Pa","10 Pa"],a:2,s:"ρgh = 1000·10·1 = 10⁴ Pa (circa 75 mmHg): basta a vincere la pressione venosa."},
{t:"u3a",k:"c",q:"Con 1 mmHg ≈ 133 Pa, una pressione di 13 300 Pa corrisponde a ____ mmHg.",a:["100","CENTO"],s:"13 300/133 = 100 mmHg."},
{t:"u3b",k:"m",q:"Un blocco di 0,2 m³ con densità 700 kg/m³ galleggia in acqua. Quale massa massima si può caricare sopra senza farlo affondare?",o:["60 kg","140 kg","200 kg","30 kg","600 kg"],a:0,s:"Al limite è tutto immerso: spinta = 1000·0,2·g. Massa totale sostenibile 200 kg, il blocco ne ha 140: carico = 60 kg."},
{t:"u3b",k:"c",q:"Una boa di volume 0,5 m³ e massa 100 kg galleggia in acqua: il volume immerso è ____ m³.",a:["0,1","0.1"],s:"All'equilibrio massa d'acqua spostata = massa della boa: 100 kg → 0,1 m³."},
{t:"u3b",k:"c",q:"Un corpo galleggia in un olio di densità 800 kg/m³ con il 75% del volume immerso: la sua densità è ____ kg/m³.",a:["600"],s:"ρ_corpo = frazione immersa·ρ_liquido = 0,75·800 = 600 kg/m³."},
{t:"u3b",k:"m",q:"Una sfera di 1 L e massa 3 kg, appesa a un dinamometro, è immersa completamente in acqua (g = 10 m/s²). Il dinamometro segna:",o:["30 N","10 N","40 N","20 N","0 N"],a:3,s:"Peso 30 N meno spinta 1000·10⁻³·10 = 10 N: peso apparente 20 N."},
{t:"u3b",k:"m",q:"Un corpo completamente immerso affonda verso il fondo di un lago. Mentre scende (acqua incomprimibile), la spinta di Archimede:",o:["aumenta con la profondità","resta costante","diminuisce","si annulla sul fondo","diventa uguale al peso"],a:1,s:"La spinta dipende dal volume immerso e dalla densità del liquido, non dalla profondità: la pressione cresce sopra e sotto allo stesso modo."},
{t:"u3b",k:"m",q:"Un uomo di 70 kg galleggia in acqua quasi completamente immerso. Il volume d'acqua spostato è circa:",o:["7 L","700 L","0,7 L","7 m³","70 L"],a:4,s:"Galleggiando sposta 70 kg d'acqua, cioè 70 dm³ = 70 L."},
{t:"u3c",k:"c",q:"Nell'aorta, di sezione 3 cm², il sangue scorre a 30 cm/s: la portata è ____ cm³/s.",a:["90","NOVANTA"],s:"Q = S·v = 3·30 = 90 cm³/s (circa 5,4 L/min)."},
{t:"u3c",k:"m",q:"La portata cardiaca è 5 L/min e la sezione complessiva dei capillari è circa 2500 cm². La velocità media del sangue nei capillari è circa:",o:["3,3 cm/s","33 cm/s","0,33 mm/s","2 cm/s","0,033 mm/s"],a:2,s:"Q ≈ 5000 cm³/60 s ≈ 83 cm³/s; v = Q/S ≈ 83/2500 ≈ 0,033 cm/s = 0,33 mm/s."},
{t:"u3c",k:"m",q:"In un tubo a sezione circolare il diametro triplica. A parità di portata la velocità del fluido:",o:["si riduce a un nono","triplica","si riduce a un terzo","aumenta di 9 volte","resta uguale"],a:0,s:"La sezione va con il quadrato del diametro (×9), quindi v diventa 1/9."},
{t:"u3c",k:"c",q:"In un tubo orizzontale l'acqua (ρ = 1000 kg/m³) passa da 2 m/s a 4 m/s: la pressione diminuisce di ____ Pa.",a:["6000"],s:"Δp = ½ρ(v₂² − v₁²) = 500·(16 − 4) = 6000 Pa. Non ½ρ(Δv)² = 2000 Pa."},
{t:"u3c",k:"m",q:"Nell'equazione di Bernoulli il termine ½ρv² rappresenta:",o:["la pressione idrostatica","l'energia potenziale per unità di massa","la portata","l'energia cinetica per unità di volume","la viscosità"],a:3,s:"p, ½ρv² e ρgh hanno tutti le dimensioni di una pressione, cioè di un'energia per unità di volume."},
{t:"u3d",k:"m",q:"Per la legge di Poiseuille, a parità di portata, se il raggio di un vaso si dimezza la differenza di pressione necessaria:",o:["raddoppia","aumenta di 16 volte","quadruplica","aumenta di 8 volte","si dimezza"],a:1,s:"Δp = Q·R con R ∝ L/r⁴: r/2 → R ×16."},
{t:"u3d",k:"c",q:"Il numero di Reynolds è Re = ρvd/η. Per il sangue con ρ = 1000 kg/m³, v = 0,4 m/s, d = 2 cm e η = 4·10⁻³ Pa·s, Re vale ____ .",a:["2000"],s:"Re = 1000·0,4·0,02/0,004 = 8/0,004 = 2000: al limite tra laminare e turbolento."},
{t:"u3d",k:"m",q:"Raddoppiando la velocità del sangue in un vaso (stessi diametro, densità e viscosità), il numero di Reynolds:",o:["si dimezza","quadruplica","resta uguale","diventa un quarto","raddoppia"],a:4,s:"Re è proporzionale a v: più velocità, più probabile la turbolenza (soffi cardiaci, stenosi)."},
{t:"u3d",k:"c",q:"Tre vasi di resistenza idraulica 6R ciascuno, collegati in parallelo, hanno resistenza equivalente ____ R.",a:["2","DUE"],s:"1/R_eq = 3/(6R) → R_eq = 2R."},
{t:"u3d",k:"m",q:"Nella legge di Poiseuille la portata è inversamente proporzionale:",o:["al raggio alla quarta","alla differenza di pressione","alla viscosità e alla lunghezza del tubo","alla densità del fluido","al quadrato della velocità"],a:2,s:"Q = πr⁴Δp/(8ηL): cresce con r⁴ e Δp, cala con η e L."},
{t:"u3e",k:"m",q:"Per la legge di Jurin, l'altezza a cui un liquido sale in un capillare è:",o:["proporzionale alla tensione superficiale e inversamente proporzionale al raggio","proporzionale al raggio del tubo","proporzionale alla densità del liquido","proporzionale al quadrato del raggio","indipendente dal raggio"],a:0,s:"h = 2τ·cos θ/(ρgr): tubi più sottili e liquidi con τ maggiore danno risalite più alte."},
{t:"u3e",k:"c",q:"La tensione superficiale si misura in N/m: è una forza per unità di ____ .",a:["LUNGHEZZA"],s:"Equivale anche a un'energia per unità di superficie (J/m²)."},
{t:"u3e",k:"m",q:"Una goccia di raggio 1 mm ha una sovrappressione interna di 140 Pa. Una goccia dello stesso liquido con raggio 0,5 mm ha sovrappressione:",o:["70 Pa","140 Pa","560 Pa","280 Pa","35 Pa"],a:3,s:"Δp = 2τ/r: dimezzando r la sovrappressione raddoppia."},
{t:"u3e",k:"m",q:"Una bolla di sapone ha due superfici (interna ed esterna). Per essa la legge di Laplace diventa:",o:["Δp = 2τ/r","Δp = 4τ/r","Δp = τ/r","Δp = τ·r","Δp = 2τ·r"],a:1,s:"Ogni superficie contribuisce 2τ/r: le due insieme danno 4τ/r. Per una goccia o un alveolo (una superficie) vale 2τ/r."},
{t:"u3e",k:"c",q:"Un liquido che bagna perfettamente una superficie forma con essa un angolo di contatto di ____ gradi.",a:["0","ZERO"],s:"θ = 0° (cos θ = 1): massima risalita capillare. Per θ > 90° il liquido non bagna e scende (mercurio)."},
{t:"u3e",k:"m",q:"Quale di questi fenomeni NON dipende dalla tensione superficiale?",o:["la forma sferica delle gocce","la risalita dell'acqua nei capillari","il collasso degli alveoli senza surfattante","un ago d'acciaio appoggiato con cura che resta a galla","il galleggiamento di una nave"],a:4,s:"La nave galleggia per la spinta di Archimede; l'ago invece è sostenuto dalla «pellicola» superficiale."},
{t:"u4a",k:"c",q:"Un'onda su una corda ha lunghezza d'onda 0,8 m e frequenza 5 Hz: la velocità di propagazione è ____ m/s.",a:["4","QUATTRO"],s:"v = λ·f = 0,8·5 = 4 m/s."},
{t:"u4a",k:"m",q:"Un suono passa dall'aria (340 m/s) all'acqua (circa 1500 m/s). La sua lunghezza d'onda:",o:["diminuisce","resta uguale","aumenta di circa 4,4 volte","si dimezza","si annulla"],a:2,s:"La frequenza resta quella della sorgente; λ = v/f cresce come v: 1500/340 ≈ 4,4."},
{t:"u4a",k:"m",q:"In un'onda trasversale le particelle del mezzo oscillano:",o:["perpendicolarmente alla direzione di propagazione","nella stessa direzione di propagazione","in cerchio attorno alla sorgente","solo nel vuoto","insieme all'onda, spostandosi con essa"],a:0,s:"Esempio: onde su una corda. Nel suono (longitudinale) l'oscillazione è parallela alla propagazione."},
{t:"u4a",k:"c",q:"Un'onda di periodo 4 ms ha frequenza ____ Hz.",a:["250"],s:"f = 1/T = 1/0,004 s = 250 Hz. Errore tipico: dimenticare i millisecondi."},
{t:"u4a",k:"m",q:"In quale mezzo il suono si propaga più velocemente?",o:["nell'aria","nell'acqua","nel vuoto","nell'acciaio","in tutti alla stessa velocità"],a:3,s:"Circa 340 m/s in aria, 1500 m/s in acqua, oltre 5000 m/s nell'acciaio; nel vuoto non si propaga."},
{t:"u4b",k:"c",q:"Un suono di intensità 10⁻⁸ W/m² ha un livello sonoro di ____ dB (soglia I₀ = 10⁻¹² W/m²).",a:["40","QUARANTA"],s:"β = 10·log(I/I₀) = 10·log(10⁴) = 40 dB."},
{t:"u4b",k:"m",q:"Due sorgenti identiche producono ciascuna 70 dB nello stesso punto. Insieme producono circa:",o:["140 dB","73 dB","70 dB","80 dB","35 dB"],a:1,s:"Le intensità si sommano (×2) e 10·log 2 ≈ 3 dB: 73 dB. I decibel non si sommano."},
{t:"u4b",k:"m",q:"Il livello di un suono scende da 90 dB a 60 dB. L'intensità è diventata:",o:["un terzo","un trentesimo","un centesimo","due terzi","un millesimo"],a:4,s:"−30 dB = tre fattori 10: I diventa 10⁻³ volte quella iniziale."},
{t:"u4b",k:"c",q:"Se l'ampiezza di un'onda sonora raddoppia (stessa frequenza), l'intensità diventa ____ volte maggiore.",a:["4","QUATTRO"],s:"I ∝ A²: 2² = 4 (il livello sale di circa 6 dB)."},
{t:"u4b",k:"m",q:"La soglia del dolore è circa 120 dB. Rispetto alla soglia di udibilità (0 dB) l'intensità è:",o:["120 volte maggiore","10¹⁰ volte maggiore","10¹² volte maggiore","12 volte maggiore","10⁶ volte maggiore"],a:2,s:"120 dB = 12 fattori 10: I = 10¹²·I₀ = 1 W/m²."},
{t:"u4c",k:"m",q:"Una sorgente sonora si avvicina a 17 m/s a un osservatore fermo (suono a 340 m/s). La frequenza percepita aumenta di circa:",o:["5%","0,5%","17%","50%","10%"],a:0,s:"f' = f·340/(340 − 17) = f·340/323 ≈ 1,05·f: circa +5% (in prima approssimazione Δf/f ≈ v/v_suono = 17/340)."},
{t:"u4c",k:"c",q:"In ecografia un'eco torna alla sonda dopo 130 µs in un tessuto in cui il suono viaggia a 1540 m/s: l'interfaccia è a circa ____ cm di profondità.",a:["10","DIECI"],s:"Andata e ritorno: d = v·t/2 = 1540·130·10⁻⁶/2 ≈ 0,10 m. Dimenticare il /2 dà 20 cm."},
{t:"u4c",k:"m",q:"L'effetto Doppler è:",o:["la variazione della velocità del suono nel mezzo","la diminuzione dell'ampiezza con la distanza","la variazione di lunghezza d'onda dovuta al cambio di mezzo","la variazione della frequenza percepita dovuta al moto relativo tra sorgente e osservatore","l'assorbimento del suono da parte dei tessuti"],a:3,s:"Non cambia la velocità dell'onda nel mezzo: cambia la frequenza ricevuta."},
{t:"u4c",k:"m",q:"Un osservatore si allontana da una sorgente sonora ferma. Rispetto a quando sta fermo, percepisce un suono:",o:["più acuto","più grave (frequenza minore)","identico","più intenso ma della stessa frequenza","senza alcun suono"],a:1,s:"Allontanandosi incontra meno fronti d'onda al secondo: frequenza percepita minore."},
{t:"u4c",k:"c",q:"In ecografia si usano ultrasuoni con frequenze dell'ordine dei ____ (kHz/MHz).",a:["MHZ","MEGAHERTZ","MEGAHERZ"],s:"Tipicamente 2–15 MHz: λ di frazioni di millimetro, quindi buona risoluzione."},
{t:"u4c",k:"m",q:"Perché in ecografia si usano frequenze più alte per le strutture superficiali e più basse per quelle profonde?",o:["a frequenza alta l'onda penetra di più","a frequenza bassa la risoluzione è migliore","la frequenza non influisce né su risoluzione né su penetrazione","le frequenze alte sono ionizzanti","a frequenza alta la risoluzione è migliore ma l'onda è più assorbita dai tessuti"],a:4,s:"λ piccola = dettagli fini, ma l'attenuazione cresce con la frequenza: è un compromesso."},
{t:"u4d",k:"c",q:"Una massa di 0,5 kg appesa a una molla con k = 50 N/m oscilla con periodo T = 2π·√(m/k) = ____ π s (scrivi il coefficiente di π).",a:["0,2","0.2"],s:"√(0,5/50) = √0,01 = 0,1 → T = 0,2π s ≈ 0,63 s."},
{t:"u4d",k:"m",q:"Quadruplicando la costante elastica della molla (stessa massa), la frequenza di oscillazione:",o:["quadruplica","si dimezza","raddoppia","resta uguale","diventa un quarto"],a:2,s:"f = (1/2π)·√(k/m): k ×4 → f ×2 (e il periodo si dimezza)."},
{t:"u4d",k:"m",q:"In un oscillatore massa-molla, nell'istante in cui la massa passa per la posizione di equilibrio:",o:["la velocità è massima e l'accelerazione nulla","la velocità è nulla e l'accelerazione massima","velocità e accelerazione sono entrambe massime","velocità e accelerazione sono entrambe nulle","l'energia potenziale elastica è massima"],a:0,s:"In equilibrio la forza elastica è zero (a = 0) e tutta l'energia è cinetica."},
{t:"u4d",k:"c",q:"Due onde della stessa frequenza, di ampiezza 3 cm e 4 cm, si sovrappongono in fase: l'ampiezza risultante è ____ cm.",a:["7","SETTE"],s:"In fase le ampiezze si sommano: 3 + 4 = 7 cm (in opposizione darebbero 1 cm)."},
{t:"u4d",k:"m",q:"Il periodo di un pendolo semplice, per piccole oscillazioni, dipende:",o:["solo dalla massa","dalla massa e dall'ampiezza","solo dall'ampiezza","dalla lunghezza del filo e da g, non dalla massa","dalla massa e da g"],a:3,s:"T = 2π·√(l/g); per la molla invece conta la massa (T = 2π·√(m/k))."},
{t:"u5a",k:"c",q:"Per scaldare 0,5 kg d'acqua da 20 °C a 100 °C (c = 4,2 kJ/(kg·K)) servono ____ kJ.",a:["168"],s:"Q = m·c·ΔT = 0,5·4,2·80 = 168 kJ."},
{t:"u5a",k:"m",q:"Una temperatura di −23 °C corrisponde a:",o:["296 K","250 K","−250 K","23 K","273 K"],a:1,s:"T = −23 + 273 = 250 K. Non esistono temperature assolute negative."},
{t:"u5a",k:"m",q:"Una variazione di temperatura di 10 °C corrisponde a una variazione di:",o:["283 K","263 K","50 K","18 K","10 K"],a:4,s:"Celsius e kelvin hanno gradini uguali: le differenze coincidono, si somma 273 solo ai valori."},
{t:"u5a",k:"c",q:"Per far evaporare 2 kg d'acqua già a 100 °C (calore latente 2260 kJ/kg) servono ____ kJ.",a:["4520"],s:"Q = m·L = 2·2260 = 4520 kJ, senza variazione di temperatura."},
{t:"u5a",k:"m",q:"Un corpo di capacità termica 500 J/K assorbe 2 kJ senza cambiare stato. La sua temperatura aumenta di:",o:["0,25 K","1000 K","4 K","40 K","2,5 K"],a:2,s:"ΔT = Q/C = 2000/500 = 4 K."},
{t:"u5a",k:"m",q:"Durante la fusione del ghiaccio a 0 °C, il calore fornito serve a:",o:["rompere i legami tra le molecole, senza aumentare la temperatura","aumentare la temperatura del ghiaccio","aumentare l'energia cinetica media delle molecole","compiere lavoro sull'ambiente","nulla: durante la fusione non si assorbe calore"],a:0,s:"È il calore latente: aumenta l'energia potenziale delle molecole, la temperatura resta 0 °C finché tutto è fuso."},
{t:"u5b",k:"m",q:"Un gas perfetto a pressione costante passa da 300 K a 450 K. Il suo volume:",o:["raddoppia","resta uguale","diminuisce di un terzo","aumenta del 50%","aumenta del 150%"],a:3,s:"A p costante V ∝ T: 450/300 = 1,5."},
{t:"u5b",k:"c",q:"In un gas perfetto (quantità fissa) si raddoppiano sia la pressione sia il volume: la temperatura assoluta diventa ____ volte quella iniziale.",a:["4","QUATTRO"],s:"pV = nRT: pV ×4 → T ×4."},
{t:"u5b",k:"m",q:"L'equazione dei gas perfetti descrive bene un gas reale quando:",o:["la pressione è alta e la temperatura bassa","la pressione è bassa e la temperatura alta","il gas è vicino a liquefarsi","le molecole sono molto grandi","sempre, senza eccezioni"],a:1,s:"A bassa densità il covolume e le attrazioni tra molecole diventano trascurabili. Nel 2025 è uscita proprio una domanda sui gas reali."},
{t:"u5b",k:"m",q:"Quante moli di gas perfetto ci sono in 44,8 L a 0 °C e 1 atm?",o:["1","0,5","4","22,4","2"],a:4,s:"In condizioni normali una mole occupa 22,4 L: 44,8/22,4 = 2 mol."},
{t:"u5b",k:"c",q:"L'energia cinetica media delle molecole di un gas perfetto è (3/2)·k_B·T: è proporzionale alla temperatura ____ (una parola).",a:["ASSOLUTA"],s:"La T va in kelvin: a 0 °C l'energia cinetica non è zero."},
{t:"u5c",k:"c",q:"Un gas si espande a pressione costante di 2·10⁵ Pa da 3 L a 8 L: il lavoro compiuto dal gas è ____ J.",a:["1000","MILLE"],s:"L = p·ΔV = 2·10⁵·5·10⁻³ = 1000 J. Errore tipico: non convertire i litri in m³."},
{t:"u5c",k:"m",q:"La stessa isobara percorsa al contrario (il gas viene compresso da 8 L a 3 L a 2·10⁵ Pa). Il lavoro compiuto dal gas è:",o:["+1000 J","0 J","−1000 J","−2000 J","+500 J"],a:2,s:"Nella compressione ΔV < 0: il lavoro del gas cambia segno (l'ambiente compie +1000 J sul gas)."},
{t:"u5c",k:"c",q:"Tre moli di gas monoatomico (c_V = 3/2·R, R ≈ 8,3 J/(mol·K)) vengono scaldate di 20 K: l'energia interna aumenta di circa ____ J.",a:["747","750"],s:"ΔU = n·c_V·ΔT = 3·12,45·20 ≈ 747 J, qualunque sia la trasformazione."},
{t:"u5c",k:"m",q:"In un'espansione isobara di un gas perfetto:",o:["Q > L e la temperatura aumenta","Q = L","Q < L","Q = 0","ΔU = 0"],a:0,s:"V aumenta a p costante → T aumenta → ΔU > 0; quindi Q = ΔU + L è maggiore di L."},
{t:"u5c",k:"m",q:"In una compressione isoterma di un gas perfetto, il gas:",o:["assorbe calore e si scalda","non scambia calore","aumenta la sua energia interna","cede all'ambiente un calore uguale al lavoro che riceve","compie lavoro positivo"],a:3,s:"T costante → ΔU = 0 → Q = L, entrambi negativi: il lavoro ricevuto esce come calore."},
{t:"u5c",k:"m",q:"Nel piano p-V una trasformazione isocora è rappresentata da:",o:["un segmento orizzontale","un segmento verticale","un ramo di iperbole","una curva più ripida dell'isoterma","una retta passante per l'origine"],a:1,s:"V costante: varia solo p. L'area sotto un segmento verticale è nulla, quindi L = 0."},
{t:"u5d",k:"c",q:"Una macchina di Carnot ha rendimento del 40% e la sorgente calda a 500 K: la sorgente fredda è a ____ K.",a:["300","TRECENTO"],s:"η = 1 − T_f/T_c → T_f = 0,6·500 = 300 K."},
{t:"u5d",k:"m",q:"Un gas si espande liberamente nel vuoto dentro un recipiente isolato (espansione libera). La sua entropia:",o:["resta costante perché Q = 0","diminuisce","si annulla","dipende dal verso dell'espansione ma non cambia","aumenta"],a:4,s:"Il processo è irreversibile: anche senza calore scambiato, l'entropia di un sistema isolato cresce (più volume = più microstati)."},
{t:"u5d",k:"m",q:"Un frigorifero porta calore dall'interno freddo all'ambiente più caldo. Questo NON viola il secondo principio perché:",o:["il calore passa spontaneamente dal freddo al caldo","l'entropia dell'universo diminuisce","il processo richiede lavoro dall'esterno","il frigorifero ha rendimento 100%","il secondo principio vale solo per i gas"],a:2,s:"Clausius vieta il passaggio spontaneo dal freddo al caldo; con lavoro esterno è possibile."},
{t:"u5d",k:"m",q:"Una macchina termica compie 300 J di lavoro e cede 700 J alla sorgente fredda a ogni ciclo. Il rendimento è:",o:["30%","43%","70%","100%","3%"],a:0,s:"Q assorbito = 300 + 700 = 1000 J; η = 300/1000 = 30%. 43% (300/700) usa il calore ceduto al posto di quello assorbito."},
{t:"u5d",k:"c",q:"Un blocco di ghiaccio a 273 K fonde assorbendo 273 kJ di calore: la sua entropia aumenta di ____ J/K.",a:["1000","MILLE"],s:"ΔS = Q/T = 273 000/273 = 1000 J/K (T costante durante la fusione)."},
{t:"u5d",k:"m",q:"Per aumentare il rendimento di una macchina di Carnot conviene:",o:["alzare la temperatura della sorgente fredda","usare un gas diverso","aumentare la massa del gas","alzare la temperatura della sorgente calda o abbassare quella della fredda","farla girare più velocemente"],a:3,s:"η = 1 − T_f/T_c dipende solo dalle due temperature assolute."},
{t:"u5e",k:"c",q:"Una parete di 5 m², spessa 10 cm, con conducibilità 0,8 W/(m·K), separa ambienti a 22 °C e 2 °C: la potenza dispersa è ____ W.",a:["800","OTTOCENTO"],s:"P = k·A·ΔT/d = 0,8·5·20/0,1 = 800 W. Lo spessore va in metri."},
{t:"u5e",k:"m",q:"Raddoppiando la differenza di temperatura e dimezzando lo spessore di una parete, la potenza dispersa per conduzione:",o:["raddoppia","quadruplica","resta uguale","si dimezza","aumenta di 8 volte"],a:1,s:"P ∝ ΔT/d: ×2 per ΔT e ×2 per lo spessore dimezzato."},
{t:"u5e",k:"m",q:"Una termocamera, usata anche in medicina, rileva soprattutto la radiazione:",o:["ultravioletta","X","visibile","gamma","infrarossa"],a:4,s:"I corpi a temperatura ambiente o corporea irraggiano soprattutto nell'infrarosso."},
{t:"u5e",k:"m",q:"Il sudore raffredda il corpo perché:",o:["è più freddo della pelle","aumenta la conduzione verso l'aria","evaporando sottrae alla pelle il calore latente di vaporizzazione","blocca l'irraggiamento","riduce la produzione di calore metabolico"],a:2,s:"Ogni grammo che evapora porta via circa 2,4 kJ."},
{t:"u5e",k:"c",q:"L'aria scaldata da un termosifone sale verso il soffitto e porta con sé il calore: questo trasporto si chiama ____ .",a:["CONVEZIONE"],s:"Nella convezione si sposta materia (il fluido); nella conduzione no."},
{t:"u5e",k:"m",q:"A parità di spessore e di differenza di temperatura, quale materiale trasmette più calore per conduzione?",o:["rame","aria ferma","legno","lana","polistirolo"],a:0,s:"I metalli hanno conducibilità termica migliaia di volte maggiore degli isolanti."},
{t:"u6a",k:"c",q:"Due cariche di 2 µC e 3 µC sono a 3 m di distanza (k = 9·10⁹ N·m²/C²): la forza tra loro vale ____ ·10⁻³ N.",a:["6","SEI"],s:"F = 9·10⁹·6·10⁻¹²/9 = 6·10⁻³ N. Ricordare il quadrato della distanza (9 m²)."},
{t:"u6a",k:"m",q:"Due sferette metalliche identiche, con cariche +6 µC e −2 µC, vengono messe a contatto e poi separate. Ciascuna ha carica:",o:["+4 µC","+8 µC","−2 µC","+2 µC","+3 µC"],a:3,s:"La carica totale (+4 µC) si conserva e si divide a metà tra sfere identiche."},
{t:"u6a",k:"m",q:"La carica elettrica è quantizzata. Ciò significa che:",o:["la carica può assumere qualunque valore","ogni carica è un multiplo intero della carica elementare e","la carica si crea per strofinio","la carica dipende dalla velocità","le cariche positive sono più grandi delle negative"],a:1,s:"q = n·e con e = 1,6·10⁻¹⁹ C."},
{t:"u6a",k:"m",q:"Si triplica una delle due cariche e si triplica anche la distanza. La forza di Coulomb:",o:["resta uguale","triplica","diventa un nono","aumenta di 9 volte","diventa un terzo"],a:4,s:"F ∝ q₁q₂/r²: ×3 per la carica, ÷9 per la distanza → ×1/3."},
{t:"u6a",k:"c",q:"Per il principio di conservazione, in un sistema isolato la carica ____ resta costante (una parola).",a:["TOTALE","NETTA","COMPLESSIVA"],s:"Strofinando non si crea carica: si spostano elettroni da un corpo all'altro."},
{t:"u6b",k:"m",q:"Un elettrone passa da un punto a potenziale 0 V a uno a +50 V. La sua energia potenziale elettrica:",o:["aumenta di 50 eV","resta invariata","diminuisce di 50 eV e l'energia cinetica aumenta di 50 eV","diminuisce di 50 J","aumenta di 50 J"],a:2,s:"U = qV con q = −e: passando a V maggiore U diminuisce; per la conservazione dell'energia K aumenta di 50 eV."},
{t:"u6b",k:"c",q:"Una carica puntiforme di 3 µC si trova a 30 cm dal punto P (k = 9·10⁹ N·m²/C²): il campo in P vale ____ ·10⁵ N/C.",a:["3","TRE"],s:"E = kq/r² = 9·10⁹·3·10⁻⁶/0,09 = 3·10⁵ N/C."},
{t:"u6b",k:"m",q:"Le linee del campo elettrico e le superfici equipotenziali sono tra loro:",o:["perpendicolari in ogni punto","parallele","inclinate di 45°","coincidenti","senza relazione"],a:0,s:"Lungo un'equipotenziale il lavoro è nullo, quindi il campo non ha componente tangente a essa."},
{t:"u6b",k:"m",q:"Il potenziale di una carica puntiforme vale V = kq/r. A distanza doppia, il potenziale:",o:["diventa un quarto","raddoppia","resta uguale","si dimezza","diventa un ottavo"],a:3,s:"V ∝ 1/r (il campo invece ∝ 1/r²): confonderli è un errore tipico."},
{t:"u6c",k:"c",q:"Un condensatore da 5 µF caricato a 20 V immagazzina un'energia di ____ mJ.",a:["1","UNO"],s:"U = ½CV² = ½·5·10⁻⁶·400 = 10⁻³ J = 1 mJ."},
{t:"u6c",k:"m",q:"Un condensatore piano carico viene staccato dal generatore e poi si raddoppia la distanza tra le armature. La d.d.p. tra le armature:",o:["si dimezza","raddoppia","resta uguale","quadruplica","si annulla"],a:1,s:"Isolato → Q costante; C si dimezza → V = Q/C raddoppia."},
{t:"u6c",k:"m",q:"In un condensatore piano (C = ε₀εᵣA/d) si raddoppia l'area delle armature e si dimezza la loro distanza. La capacità:",o:["raddoppia","resta uguale","si dimezza","aumenta di 8 volte","quadruplica"],a:4,s:"×2 per l'area e ×2 per la distanza dimezzata."},
{t:"u6c",k:"c",q:"Un condensatore porta una carica di 30 µC con una d.d.p. di 6 V: la sua capacità è ____ µF.",a:["5","CINQUE"],s:"C = Q/V = 30/6 = 5 µF (relazione V = Q/C, uscita nel 2025)."},
{t:"u6c",k:"m",q:"Tre condensatori da 6 µF collegati in serie equivalgono a:",o:["18 µF","6 µF","2 µF","3 µF","0,5 µF"],a:2,s:"In serie si sommano gli inversi: 1/C = 3/6 → C = 2 µF (al contrario delle resistenze)."},
{t:"u6d",k:"m",q:"Un filo ha resistenza 8 Ω. Un filo dello stesso materiale e della stessa lunghezza, ma con diametro doppio, ha resistenza:",o:["2 Ω","4 Ω","16 Ω","32 Ω","8 Ω"],a:0,s:"R = ρL/S; diametro doppio → sezione ×4 → R/4 = 2 Ω."},
{t:"u6d",k:"c",q:"Tre resistenze da 2 Ω, 4 Ω e 6 Ω in serie sono collegate a un generatore ideale da 24 V: la corrente è ____ A.",a:["2","DUE"],s:"R = 12 Ω; I = 24/12 = 2 A."},
{t:"u6d",k:"m",q:"Una resistenza da 6 Ω e una da 3 Ω sono collegate in serie a un generatore ideale da 18 V. La tensione ai capi della resistenza da 6 Ω è:",o:["6 V","18 V","9 V","12 V","3 V"],a:3,s:"I = 18/9 = 2 A; V = 6·2 = 12 V: in serie la tensione si divide in proporzione alle resistenze."},
{t:"u6d",k:"m",q:"In un collegamento in parallelo di resistenze diverse, è uguale per tutte:",o:["la corrente","la tensione ai loro capi","la potenza dissipata","la resistenza","il calore prodotto"],a:1,s:"In parallelo la d.d.p. è la stessa; la corrente si divide (più corrente nella resistenza minore)."},
{t:"u6d",k:"c",q:"Un asciugacapelli da 1100 W funziona a 220 V: la sua resistenza è ____ Ω.",a:["44"],s:"R = V²/P = 48 400/1100 = 44 Ω (corrente 5 A)."},
{t:"u6e",k:"m",q:"Un protone e un elettrone entrano con la stessa velocità, perpendicolarmente, nello stesso campo magnetico uniforme. Rispetto all'elettrone, il protone descrive una circonferenza:",o:["di raggio uguale, nello stesso verso","di raggio minore, nello stesso verso","di raggio uguale, in verso opposto","non descrive una circonferenza","di raggio molto maggiore, percorsa in verso opposto"],a:4,s:"r = mv/(qB): stessa |q|, massa circa 1836 volte maggiore; carica di segno opposto → verso opposto."},
{t:"u6e",k:"c",q:"Una carica di 2 µC si muove a 500 m/s perpendicolarmente a un campo magnetico di 0,4 T: la forza di Lorentz vale ____ ·10⁻⁴ N.",a:["4","QUATTRO"],s:"F = qvB = 2·10⁻⁶·500·0,4 = 4·10⁻⁴ N."},
{t:"u6e",k:"m",q:"Le linee del campo magnetico generato da un filo rettilineo percorso da corrente sono:",o:["rette parallele al filo","rette radiali uscenti dal filo","circonferenze concentriche attorno al filo, in piani perpendicolari a esso","eliche attorno al filo","linee che partono dal filo e vanno all'infinito"],a:2,s:"Il verso si trova con la regola della mano destra (pollice nel verso della corrente)."},
{t:"u6e",k:"m",q:"Il lavoro compiuto dalla forza magnetica su una carica in moto è:",o:["nullo, perché la forza è sempre perpendicolare alla velocità","positivo","negativo","uguale a qvB","dipende dal segno della carica"],a:0,s:"La forza di Lorentz cambia la direzione della velocità ma non il modulo: l'energia cinetica resta costante."},
{t:"u7a",k:"m",q:"Un fotone ha energia doppia di un altro. La sua lunghezza d'onda è:",o:["doppia","uguale","quadrupla","metà","un quarto"],a:3,s:"E = hf = hc/λ: E e λ sono inversamente proporzionali."},
{t:"u7a",k:"c",q:"Un'onda elettromagnetica di frequenza 6·10¹⁴ Hz nel vuoto ha lunghezza d'onda ____ nm.",a:["500","CINQUECENTO"],s:"λ = c/f = 3·10⁸/6·10¹⁴ = 5·10⁻⁷ m = 500 nm (luce verde)."},
{t:"u7a",k:"m",q:"Quale sequenza è ordinata dal fotone meno energetico al più energetico?",o:["raggi gamma, ultravioletto, infrarosso, onde radio","onde radio, infrarosso, ultravioletto, raggi gamma","infrarosso, onde radio, raggi X, ultravioletto","visibile, microonde, raggi X, onde radio","ultravioletto, visibile, infrarosso, raggi X"],a:1,s:"L'energia cresce con la frequenza: radio < microonde < IR < visibile < UV < X < γ."},
{t:"u7a",k:"c",q:"Nel vuoto tutte le onde elettromagnetiche viaggiano con la stessa ____ (una parola).",a:["VELOCITÀ","VELOCITA"],s:"c ≈ 3·10⁸ m/s, qualunque sia la frequenza."},
{t:"u7a",k:"m",q:"L'intensità di un'onda elettromagnetica è proporzionale:",o:["all'ampiezza del campo elettrico","alla lunghezza d'onda","all'inverso della frequenza","alla velocità della luce al quadrato","al quadrato dell'ampiezza del campo elettrico"],a:4,s:"Come per le onde meccaniche, I ∝ E₀²."},
{t:"u7b",k:"m",q:"Un raggio di luce entra in un blocco di vetro (n = 1,5) perpendicolarmente alla superficie (incidenza 0°). Il raggio:",o:["si avvicina alla normale","si allontana dalla normale","prosegue senza deviare, ma rallenta","viene riflesso totalmente","si ferma"],a:2,s:"Con incidenza nulla sin r = 0: nessuna deviazione, ma la velocità scende a c/1,5."},
{t:"u7b",k:"c",q:"In un mezzo con indice di rifrazione 1,2 la luce viaggia a ____ ·10⁸ m/s.",a:["2,5","2.5"],s:"v = c/n = 3·10⁸/1,2 = 2,5·10⁸ m/s."},
{t:"u7b",k:"m",q:"In una fibra ottica, il nucleo centrale (core) deve avere un indice di rifrazione:",o:["maggiore di quello del rivestimento","minore di quello del rivestimento","uguale a quello del rivestimento","uguale a 1","nullo"],a:0,s:"La riflessione totale avviene solo passando verso un mezzo meno rifrangente."},
{t:"u7b",k:"m",q:"Un raggio passa dal vetro (n = 1,5) all'aria con angolo di incidenza di 30°. Il raggio:",o:["si avvicina alla normale","subisce riflessione totale","prosegue senza deviare","esce rifratto allontanandosi dalla normale","viene completamente assorbito"],a:3,s:"sin r = 1,5·sin 30° = 0,75 < 1: c'è rifrazione (r ≈ 49°). L'angolo limite (≈ 42°) non è superato."},
{t:"u7b",k:"c",q:"Un raggio incide su uno specchio piano formando 50° con la superficie dello specchio: l'angolo di riflessione, misurato dalla normale, è ____ gradi.",a:["40","QUARANTA"],s:"Gli angoli si misurano dalla normale: 90° − 50° = 40°. È una trappola frequente."},
{t:"u7b",k:"m",q:"L'angolo limite per la riflessione totale (sin θ_L = n₂/n₁) è tanto più piccolo quanto:",o:["più piccolo è n₁","più grande è il rapporto n₁/n₂","più grande è n₂","più bassa è la frequenza della luce","più spesso è il materiale"],a:1,s:"Un salto di indice più grande dà un angolo limite più piccolo (diamante: ~24°)."},
{t:"u7c",k:"m",q:"Con una lente convergente di distanza focale 10 cm si vuole un'immagine reale e ingrandita. L'oggetto va posto:",o:["a meno di 10 cm","esattamente a 20 cm","oltre 20 cm","esattamente nel fuoco","tra 10 e 20 cm dalla lente"],a:4,s:"Tra f e 2f l'immagine è reale, capovolta e ingrandita (domanda uscita nel 2025)."},
{t:"u7c",k:"c",q:"Una lente divergente con distanza focale −25 cm ha un potere diottrico di ____ diottrie.",a:["-4","−4","MENO 4"],s:"P = 1/f = 1/(−0,25 m) = −4 D. La focale va in metri."},
{t:"u7c",k:"m",q:"Un oggetto è a 12 cm da una lente convergente con f = 4 cm. L'immagine si forma a:",o:["3 cm dalla lente, reale","8 cm dalla lente, virtuale","6 cm dalla lente, reale","12 cm dalla lente, reale","16 cm dalla lente, reale"],a:2,s:"1/q = 1/4 − 1/12 = 2/12 → q = 6 cm, dall'altra parte: reale e rimpicciolita (m = 0,5)."},
{t:"u7c",k:"c",q:"Un oggetto è a 60 cm da una lente convergente con f = 20 cm: l'immagine si forma a ____ cm dalla lente.",a:["30","TRENTA"],s:"1/q = 1/20 − 1/60 = 2/60 → q = 30 cm."},
{t:"u7c",k:"m",q:"Una lente divergente forma di un oggetto reale un'immagine sempre:",o:["virtuale, diritta e rimpicciolita","reale, capovolta e ingrandita","reale, diritta e rimpicciolita","virtuale, capovolta e ingrandita","all'infinito"],a:0,s:"I raggi divergono dopo la lente: l'immagine sta dalla parte dell'oggetto, più piccola e diritta."},
{t:"u7d",k:"c",q:"Una soluzione trasmette il 25% della luce in una cuvetta da 1 cm: in una cuvetta da 2 cm trasmette il ____ %.",a:["6,25","6.25"],s:"Ogni centimetro moltiplica l'intensità per 0,25: 0,25² = 0,0625. Non 12,5%: la legge è esponenziale."},
{t:"u7d",k:"m",q:"La trasmittanza T = I/I₀ e l'assorbanza A sono legate da:",o:["A = 1 − T","A = 1/T","A = T²","A = −log₁₀ T","A = log₁₀ T"],a:3,s:"T = 10^(−A); per esempio T = 0,1 ↔ A = 1."},
{t:"u7d",k:"m",q:"Una soluzione ha assorbanza 3. La frazione di luce trasmessa è:",o:["3%","0,1%","30%","1%","0,3%"],a:1,s:"T = 10⁻³ = 0,1%."},
{t:"u7d",k:"c",q:"Con ε = 200 L/(mol·cm), cammino ottico 1 cm e assorbanza 0,4, la concentrazione è ____ mol/L.",a:["0,002","0.002"],s:"c = A/(ε·l) = 0,4/200 = 0,002 mol/L = 2 mmol/L."},
{t:"u7d",k:"m",q:"Se l'assorbanza di un campione aumenta di 1, l'intensità trasmessa:",o:["diminuisce di 1 W/m²","si dimezza","diventa nulla","aumenta di 10 volte","diventa un decimo"],a:4,s:"A è un logaritmo in base 10: +1 di assorbanza = trasmissione divisa per 10."},
{t:"u7d",k:"m",q:"La legge di Lambert-Beer smette di valere bene quando:",o:["il cammino ottico è 1 cm","la luce è monocromatica","la soluzione è molto concentrata o torbida","la concentrazione è bassa","il solvente è acqua"],a:2,s:"A concentrazioni alte le molecole interagiscono e la torbidità diffonde la luce: A non è più proporzionale a c."},
{t:"u7e",k:"m",q:"Un campione contiene 10¹² nuclei radioattivi con emivita di 2 giorni. Dopo 8 giorni ne restano:",o:["6,25·10¹⁰","2,5·10¹¹","1,25·10¹¹","0","2,5·10¹⁰"],a:0,s:"8 giorni = 4 emivite: 10¹²/16 = 6,25·10¹⁰."},
{t:"u7e",k:"c",q:"L'attività di una sorgente scende da 1200 Bq a 150 Bq in 30 ore: l'emivita è ____ ore.",a:["10","DIECI"],s:"1200 → 600 → 300 → 150: tre dimezzamenti in 30 h, quindi 10 h ciascuno."},
{t:"u7e",k:"m",q:"Nel decadimento β⁺ il numero atomico Z:",o:["aumenta di 1","resta uguale","diminuisce di 2","diminuisce di 1","aumenta di 2"],a:3,s:"Un protone diventa neutrone emettendo un positrone: Z − 1, A invariato."},
{t:"u7e",k:"m",q:"Il radon-222 (Z = 86) emette una particella α. Il nucleo figlio ha:",o:["Z = 88, A = 226","Z = 84, A = 218","Z = 86, A = 218","Z = 84, A = 222","Z = 85, A = 222"],a:1,s:"Decadimento α: A − 4, Z − 2."},
{t:"u7e",k:"c",q:"Un becquerel corrisponde a un decadimento al ____ .",a:["SECONDO","S"],s:"1 Bq = 1 s⁻¹; il vecchio curie vale 3,7·10¹⁰ Bq."},
{t:"u7e",k:"m",q:"L'attività di un campione radioattivo è:",o:["costante nel tempo","proporzionale al tempo trascorso","indipendente dalla costante di decadimento","proporzionale alla massa dei nuclei già decaduti","proporzionale al numero di nuclei non ancora decaduti (A = λN)"],a:4,s:"Per questo anche l'attività si dimezza a ogni emivita."}
);

const F16=id=>FIS_TOPICS.find(t=>t.id===id);
F16("u1a").es.push({q:"Classifica massa, temperatura, volume, pressione, energia interna, densità e capacità termica in intensive ed estensive.",p:["Prova mentale: divido il sistema in due metà uguali.","Si dimezzano: massa, volume, energia interna, capacità termica → estensive.","Restano uguali: temperatura, pressione, densità → intensive.","Controllo: il rapporto di due estensive (massa/volume) è intensivo."],r:"Estensive: massa, volume, energia interna, capacità termica. Intensive: temperatura, pressione, densità."});
F16("u1b").es.push({q:"Un'auto passa da 0 a 72 km/h in 4 s. Quanto vale l'accelerazione in m/s²?",p:["Cosa so: Δv = 72 km/h, Δt = 4 s; cerco a in m/s².","Converto prima: 72/3,6 = 20 m/s.","a = Δv/Δt = 20/4 = 5 m/s².","Controllo: 72/4 = 18 «km/h al secondo» è un risultato in unità miste, non accettabile."],r:"a = 5 m/s² (convertire sempre le velocità in m/s prima di dividere per il tempo)"});
F16("u1c").es.push({q:"Due forze di 6 N (verso est) e 8 N (verso nord) agiscono sullo stesso punto. Quanto vale la risultante e quale angolo forma con l'est?",p:["Le forze sono perpendicolari: uso Pitagora.","|R| = √(36 + 64) = √100 = 10 N.","tan θ = 8/6 ≈ 1,33 → θ ≈ 53° (tra 45° e 60°, perché la componente nord è maggiore).","Controllo: 10 N sta tra 8 − 6 = 2 N e 8 + 6 = 14 N."],r:"R = 10 N, inclinata di circa 53° sull'est verso nord"});
F16("u1d").es.push({q:"Verifica dimensionalmente se la portata di Poiseuille Q = πr⁴Δp/(8ηL) si misura in m³/s.",p:["[r⁴] = m⁴; [Δp] = Pa = kg/(m·s²); [η] = Pa·s = kg/(m·s); [L] = m.","Numeratore: m⁴·kg/(m·s²) = kg·m³/s².","Denominatore: kg/(m·s)·m = kg/s.","Rapporto: (kg·m³/s²)/(kg/s) = m³/s."],r:"La formula è dimensionalmente corretta: Q in m³/s (π e 8 sono numeri puri)"});
F16("u2a").es.push({q:"Un'auto viaggia a 108 km/h; il guidatore vede un ostacolo, reagisce dopo 1 s e poi frena con decelerazione 6 m/s². Quanta strada percorre prima di fermarsi?",p:["Converto: 108 km/h = 30 m/s.","Tempo di reazione (moto uniforme): s₁ = 30·1 = 30 m.","Frenata (v² = v₀² − 2as): s₂ = 900/(2·6) = 75 m.","Totale: 30 + 75 = 105 m."],r:"105 m: il tempo di reazione da solo vale quasi un terzo dello spazio di arresto"});
F16("u2b").es.push({q:"Una centrifuga fa ruotare una provetta a 10 cm dall'asse compiendo 50 giri al secondo. Quanto vale l'accelerazione centripeta, in multipli di g? (π² ≈ 10)",p:["ω = 2πf = 2π·50 = 100π rad/s.","a = ω²r = (100π)²·0,1 = 10⁴·π²·0,1 ≈ 10⁴·10·0,1 = 10⁴ m/s².","In multipli di g: 10⁴/10 = 1000 g."],r:"a ≈ 10⁴ m/s², cioè circa 1000 g: è ciò che separa le cellule dal plasma"});
F16("u2c").es.push({q:"Una cassa di 10 kg è ferma su un piano inclinato di 30°. Quanto deve valere almeno il coefficiente di attrito statico perché non scivoli? (g = 10 m/s², tan 30° ≈ 0,58)",p:["Scompongo il peso: P∥ = mg sin 30° = 50 N; P⊥ = mg cos 30° ≈ 87 N.","Reazione normale N = P⊥ ≈ 87 N.","Equilibrio: attrito statico necessario = P∥ = 50 N ≤ µ_s·N.","µ_s ≥ 50/87 = tan 30° ≈ 0,58."],r:"µ_s ≥ 0,58 (in generale µ_s ≥ tan θ, indipendente dalla massa)"});
F16("u2d").es.push({q:"Un corpo di 2 kg scende da fermo lungo uno scivolo alto 5 m e arriva in fondo a 8 m/s. Quanta energia ha dissipato l'attrito? (g = 10 m/s²)",p:["Energia iniziale: mgh = 2·10·5 = 100 J (cinetica nulla).","Energia finale: ½mv² = ½·2·64 = 64 J (potenziale nulla).","Energia dissipata = 100 − 64 = 36 J = |lavoro dell'attrito|.","Controllo: senza attrito arriverebbe a √(2gh) = 10 m/s > 8 m/s, quindi coerente."],r:"36 J dissipati (lavoro dell'attrito −36 J)"});
F16("u2e").es.push({q:"Una persona regge in mano un peso di 30 N con l'avambraccio orizzontale; il peso è a 30 cm dal gomito, il bicipite si inserisce a 5 cm e l'avambraccio (15 N) ha il baricentro a 15 cm. Che forza fa il bicipite?",p:["Fulcro = gomito; somma dei momenti nulla.","Momenti che fanno scendere: 30·0,30 + 15·0,15 = 9 + 2,25 = 11,25 N·m.","Momento del bicipite: F·0,05.","F = 11,25/0,05 = 225 N."],r:"F = 225 N, più di 5 volte il carico totale: leva di 3° genere, svantaggiosa"});
F16("u2f").es.push({q:"Un proiettile di 20 g a 300 m/s si conficca in un blocco di legno di 2,98 kg fermo su un piano liscio. Velocità dopo l'urto ed energia dissipata?",p:["Urto completamente anelastico: si conserva solo p.","p = 0,02·300 = 6 kg·m/s; massa finale 3 kg → v' = 2 m/s.","K prima = ½·0,02·90 000 = 900 J; K dopo = ½·3·4 = 6 J.","Dissipati 894 J (calore e deformazione)."],r:"v' = 2 m/s; si perde oltre il 99% dell'energia cinetica"});
F16("u3a").es.push({q:"Un sub scende a 40 m in mare (ρ ≈ 1000 kg/m³, g = 10 m/s²). Quanto vale la pressione assoluta e di quanto si riduce il volume di un palloncino d'aria (temperatura costante) rispetto alla superficie?",p:["Pressione idrostatica: ρgh = 1000·10·40 = 4·10⁵ Pa = 4 atm.","Pressione assoluta: 4 + 1 = 5 atm (non dimenticare l'atmosfera).","Boyle: p·V costante → V = V₀/5.","Controllo: a 10 m (2 atm) il volume sarebbe già la metà."],r:"p = 5 atm; il volume del palloncino si riduce a un quinto"});
F16("u3b").es.push({q:"Una zattera di 2 m³ con densità 500 kg/m³ galleggia in acqua. Quante persone da 75 kg può portare senza affondare? (g si semplifica)",p:["Massa zattera: 500·2 = 1000 kg.","Al limite tutta immersa: massa d'acqua spostata = 1000·2 = 2000 kg.","Carico massimo = 2000 − 1000 = 1000 kg.","Persone: 1000/75 ≈ 13,3 → 13 persone."],r:"13 persone (con 14 la zattera affonderebbe)"});
F16("u3c").es.push({q:"In un'arteria di sezione 0,8 cm² il sangue scorre a 25 cm/s. Una stenosi riduce la sezione a 0,2 cm². Velocità nel restringimento e calo di pressione? (ρ ≈ 1000 kg/m³)",p:["Continuità: S₁v₁ = S₂v₂ → v₂ = 25·0,8/0,2 = 100 cm/s = 1 m/s.","Bernoulli (stessa quota): Δp = ½ρ(v₂² − v₁²).","Δp = 500·(1 − 0,0625) ≈ 470 Pa (circa 3,5 mmHg).","La pressione laterale scende nella stenosi: la parete tende a collassare."],r:"v₂ = 1 m/s; Δp ≈ 470 Pa"});
F16("u3d").es.push({q:"Due vasi in parallelo hanno resistenze idrauliche R e 3R; la portata totale è 4 mL/s. Come si divide la portata?",p:["In parallelo la Δp è la stessa per i due vasi.","Q = Δp/R: la portata è inversamente proporzionale alla resistenza.","Rapporto Q₁ : Q₂ = 3 : 1 → Q₁ = 3 mL/s, Q₂ = 1 mL/s.","R equivalente: R·3R/(4R) = 0,75 R, minore della più piccola."],r:"3 mL/s nel vaso con resistenza R, 1 mL/s in quello con 3R"});
F16("u3e").es.push({q:"Un alveolo di raggio 0,1 mm ha tensione superficiale 0,05 N/m senza surfattante e 0,005 N/m con surfattante. Quale pressione serve a tenerlo aperto nei due casi?",p:["Laplace per una superficie sferica: Δp = 2τ/r.","Senza surfattante: 2·0,05/10⁻⁴ = 1000 Pa.","Con surfattante: 2·0,005/10⁻⁴ = 100 Pa.","Il surfattante riduce di 10 volte lo sforzo respiratorio."],r:"1000 Pa senza surfattante, 100 Pa con surfattante"});
F16("u4a").es.push({q:"Un'onda su una corda ha equazione y = 0,05·sin(4x − 20t) in unità SI. Ricava ampiezza, λ, f e velocità.",p:["Ampiezza: A = 0,05 m.","k = 4 rad/m → λ = 2π/4 ≈ 1,57 m.","ω = 20 rad/s → f = 20/2π ≈ 3,2 Hz.","v = ω/k = 20/4 = 5 m/s (verso +x)."],r:"A = 5 cm, λ ≈ 1,57 m, f ≈ 3,2 Hz, v = 5 m/s"});
F16("u4b").es.push({q:"Un trapano produce 90 dB a 1 m. A quale distanza il livello scende a 70 dB? (sorgente puntiforme)",p:["−20 dB = intensità divisa per 100.","I ∝ 1/r²: per dividere I per 100 la distanza va moltiplicata per 10.","r = 10 m.","Controllo: ogni raddoppio di distanza toglie circa 6 dB."],r:"a 10 m"});
F16("u4c").es.push({q:"Un'ambulanza emette 700 Hz e si avvicina a 20 m/s (suono a 340 m/s). Che frequenza si sente? E quando si allontana?",p:["Avvicinamento: f' = f·v/(v − v_s) = 700·340/320 ≈ 744 Hz.","Allontanamento: f' = 700·340/360 ≈ 661 Hz.","Variazione relativa circa ±6% (≈ v_s/v = 20/340).","Durante il passaggio il tono «scende» di circa 80 Hz."],r:"≈ 744 Hz in avvicinamento, ≈ 661 Hz in allontanamento"});
F16("u4d").es.push({q:"Una massa di 1 kg appesa a una molla la allunga di 10 cm (g = 10 m/s²). Quanto vale il periodo delle oscillazioni? (π ≈ 3,14)",p:["Equilibrio: k·x = mg → k = 10/0,1 = 100 N/m.","T = 2π·√(m/k) = 2π·√(1/100) = 2π·0,1.","T ≈ 0,63 s; f ≈ 1,6 Hz.","Controllo: T dipende da m e k, non dall'ampiezza dell'oscillazione."],r:"T ≈ 0,63 s"});
F16("u5a").es.push({q:"Quanto calore serve per trasformare 1 kg di ghiaccio a −10 °C in acqua a 20 °C? (c_ghiaccio ≈ 2,1 kJ/(kg·K), L_f = 334 kJ/kg, c_acqua = 4,2 kJ/(kg·K))",p:["Riscaldo il ghiaccio fino a 0 °C: Q₁ = 1·2,1·10 = 21 kJ.","Fondo a 0 °C: Q₂ = 1·334 = 334 kJ.","Riscaldo l'acqua da 0 a 20 °C: Q₃ = 1·4,2·20 = 84 kJ.","Totale: 21 + 334 + 84 = 439 kJ."],r:"Q ≈ 439 kJ: la fusione da sola vale più di tre quarti del totale"});
F16("u5b").es.push({q:"Una bombola da 10 L contiene ossigeno a 27 °C e 30 atm. Che volume occuperebbe il gas a 1 atm e 27 °C? E a quale pressione arriverebbe la bombola chiusa a 77 °C?",p:["T costante: p₁V₁ = p₂V₂ → V₂ = 30·10/1 = 300 L.","V costante: p/T costante, con T in kelvin: 300 K → 350 K.","p₂ = 30·350/300 = 35 atm.","Controllo: usare i °C (77/27) darebbe un assurdo 85 atm."],r:"300 L a pressione atmosferica; 35 atm a 77 °C"});
F16("u5c").es.push({q:"Due moli di gas monoatomico si espandono a pressione costante di 10⁵ Pa da 20 L a 30 L. Calcola L, ΔU e Q. (c_V = 3/2·R)",p:["L = p·ΔV = 10⁵·10·10⁻³ = 1000 J.","Da pV = nRT: nRΔT = pΔV = 1000 J.","ΔU = n·(3/2)R·ΔT = 1,5·1000 = 1500 J.","Q = ΔU + L = 2500 J (= n·c_p·ΔT = 2,5·1000)."],r:"L = 1000 J, ΔU = 1500 J, Q = 2500 J"});
F16("u5d").es.push({q:"Una macchina reale lavora tra 400 K e 300 K, assorbe 2000 J per ciclo e compie 300 J di lavoro. È possibile? Quanto calore cede?",p:["Rendimento reale: 300/2000 = 15%.","Rendimento massimo (Carnot): 1 − 300/400 = 25%.","15% < 25%: la macchina è possibile.","Calore ceduto alla sorgente fredda: 2000 − 300 = 1700 J."],r:"Possibile (15% < 25%); cede 1700 J a ogni ciclo"});
F16("u5e").es.push({q:"Una finestra di vetro di 2 m², spessa 4 mm (k ≈ 1 W/(m·K)), separa 20 °C da 0 °C. Quanta potenza perde? E con un doppio vetro che contiene 1 cm d'aria (k ≈ 0,025)?",p:["Vetro singolo: P = k·A·ΔT/d = 1·2·20/0,004 = 10 000 W (stima teorica).","Strato d'aria: P = 0,025·2·20/0,01 = 100 W.","L'aria ferma conduce circa 40 volte meno del vetro.","In pratica le pellicole d'aria sulle superfici riducono molto la stima del vetro singolo."],r:"≈ 10 kW teorici con il vetro singolo, ≈ 100 W attraverso l'intercapedine d'aria"});
F16("u6a").es.push({q:"Due cariche di +4 µC e +1 µC sono a 30 cm. In quale punto del segmento che le unisce una terza carica sarebbe in equilibrio?",p:["Nel punto cercato i due campi (opposti) hanno lo stesso modulo: k·4/x² = k·1/(0,3 − x)².","Radice: 2/x = 1/(0,3 − x) → 2(0,3 − x) = x.","0,6 = 3x → x = 0,2 m dalla carica da 4 µC.","Controllo: il punto è più vicino alla carica più piccola."],r:"a 20 cm dalla carica di 4 µC (10 cm da quella di 1 µC)"});
F16("u6b").es.push({q:"Un protone parte da fermo e attraversa una d.d.p. di 2000 V. Quanta energia cinetica acquista e con che velocità esce? (m ≈ 1,6·10⁻²⁷ kg, e = 1,6·10⁻¹⁹ C)",p:["Conservazione dell'energia: K = q·ΔV = e·2000 = 2000 eV.","In joule: 1,6·10⁻¹⁹·2000 = 3,2·10⁻¹⁶ J.","v = √(2K/m) = √(2·3,2·10⁻¹⁶/1,6·10⁻²⁷) = √(4·10¹¹) ≈ 6,3·10⁵ m/s.","Controllo: molto minore di c, quindi la meccanica classica va bene."],r:"K = 2 keV = 3,2·10⁻¹⁶ J; v ≈ 6,3·10⁵ m/s"});
F16("u6c").es.push({q:"Un condensatore da 4 µF e uno da 12 µF sono collegati in serie a 16 V. Capacità equivalente, carica e tensione su ciascuno?",p:["Serie: 1/C = 1/4 + 1/12 = 4/12 → C = 3 µF.","Carica (uguale per entrambi): Q = C·V = 3·16 = 48 µC.","V₁ = 48/4 = 12 V; V₂ = 48/12 = 4 V.","Controllo: 12 + 4 = 16 V; il condensatore più piccolo ha la tensione maggiore."],r:"C = 3 µF; Q = 48 µC; 12 V sul 4 µF e 4 V sul 12 µF"});
F16("u6d").es.push({q:"Una resistenza da 2 Ω è in serie al parallelo di due resistenze da 6 Ω e 3 Ω; il generatore ideale dà 12 V. Corrente totale e corrente nella resistenza da 6 Ω?",p:["Parallelo: 6·3/(6 + 3) = 2 Ω.","Totale: 2 + 2 = 4 Ω → I = 12/4 = 3 A.","Tensione sul parallelo: 3·2 = 6 V.","Nella 6 Ω: 6/6 = 1 A (e 2 A nella 3 Ω)."],r:"I = 3 A; 1 A nella resistenza da 6 Ω"});
F16("u6e").es.push({q:"Un elettrone (m ≈ 9·10⁻³¹ kg, e = 1,6·10⁻¹⁹ C) a 1,6·10⁷ m/s entra perpendicolarmente in un campo magnetico di 10⁻³ T. Raggio della traiettoria?",p:["La forza di Lorentz fa da forza centripeta: evB = mv²/r.","r = mv/(eB) = 9·10⁻³¹·1,6·10⁷/(1,6·10⁻¹⁹·10⁻³).","r = 9·10⁻²⁴/10⁻²² ≈ 9·10⁻² m.","Controllo: velocità o massa maggiori → raggio maggiore; campo più forte → raggio minore."],r:"r ≈ 9 cm"});
F16("u7a").es.push({q:"Una lampada UV emette fotoni da 248 nm. Quanta energia ha ogni fotone? Sono ionizzanti? (hc ≈ 1240 eV·nm)",p:["E = hc/λ = 1240/248 = 5 eV.","Soglia indicativa di ionizzazione: circa 10 eV.","5 eV < 10 eV: non ionizzanti, ma abbastanza energetici da danneggiare il DNA (germicidi).","Controllo: luce visibile (400–700 nm) → circa 1,8–3,1 eV."],r:"E = 5 eV per fotone: UV non ionizzante, ma biologicamente attivo"});
F16("u7b").es.push({q:"Un raggio passa dall'aria all'acqua (n = 4/3) con incidenza di 53° (sin 53° ≈ 0,8). Angolo di rifrazione e velocità nell'acqua?",p:["Snell: 1·sin 53° = (4/3)·sin r → sin r = 0,8·3/4 = 0,6.","r ≈ 37°: il raggio si avvicina alla normale.","v = c/n = 3·10⁸·3/4 = 2,25·10⁸ m/s.","La frequenza resta uguale, la lunghezza d'onda si riduce di un fattore 4/3."],r:"r ≈ 37°; v = 2,25·10⁸ m/s"});
F16("u7c").es.push({q:"Una lente convergente da +5 D forma l'immagine di un oggetto alto 2 cm posto a 30 cm. Dove si forma, quanto è alta e com'è?",p:["f = 1/5 m = 20 cm.","1/q = 1/20 − 1/30 = 1/60 → q = 60 cm.","m = −q/p = −60/30 = −2: altezza 4 cm, capovolta.","Oggetto tra f e 2f → immagine reale, capovolta, ingrandita (come atteso)."],r:"q = 60 cm; immagine reale, capovolta, alta 4 cm"});
F16("u7d").es.push({q:"Uno standard 0,2 mmol/L ha assorbanza 0,5; un campione dello stesso analita nella stessa cuvetta ha assorbanza 0,8. Concentrazione del campione? Che percentuale di luce trasmette lo standard? (10^0,5 ≈ 3,16)",p:["A ∝ c a parità di ε e cammino: c = 0,2·0,8/0,5 = 0,32 mmol/L.","Trasmittanza dello standard: T = 10^(−0,5) = 1/3,16 ≈ 0,32.","Lo standard trasmette circa il 32% della luce.","Controllo: A doppia non significa trasmittanza dimezzata, ma elevata al quadrato."],r:"c ≈ 0,32 mmol/L; lo standard trasmette circa il 32%"});
F16("u7e").es.push({q:"Il fluoro-18 (T½ ≈ 110 min) usato in PET viene preparato con un'attività di 400 MBq. Quanta attività resta dopo 5 h 30 min?",p:["Tempo trascorso: 330 min = 3 emivite.","Fattore: (1/2)³ = 1/8.","Attività: 400/8 = 50 MBq.","Controllo: dopo una sola emivita si sarebbe a 200 MBq."],r:"A = 50 MBq (un ottavo dell'iniziale)"});
F16("u1a").sp.push("Come si ragiona negli esercizi: le domande su questo argomento sono quasi sempre di riconoscimento. Per «fondamentale o derivata» ricorda le sette unità fondamentali (m, kg, s, A, K, mol, cd): tutto il resto (newton, joule, pascal, watt, volt, coulomb, litro) è derivato. Per «intensiva o estensiva» fai la prova del taglio a metà: se la grandezza si dimezza è estensiva, se resta uguale è intensiva. Per «scalare o vettoriale» chiediti se ha senso una direzione: forza, velocità, accelerazione, quantità di moto, campi sono vettori; energia, lavoro, pressione, temperatura sono scalari. Attenzione ai prefissi maiuscoli e minuscoli (M = 10⁶, m = 10⁻³).");
F16("u1b").sp.push("Come si ragiona negli esercizi: nel 2025 le conversioni sono uscite in tutte le prove e sono la prima fonte di errori veloci. Metodo: scrivi l'unità di partenza come prodotto di fattori e sostituisci ciascun fattore (km = 10³ m, h = 3600 s, cm³ = 10⁻⁶ m³, L = dm³ = 10⁻³ m³, atm ≈ 10⁵ Pa, mmHg ≈ 133 Pa). Per le unità al quadrato o al cubo eleva anche il fattore (1 cm² = 10⁻⁴ m², 1 cm³ = 10⁻⁶ m³). Per le accelerazioni converti prima la velocità in m/s e poi dividi per i secondi. Controllo finale: il numero deve diventare più grande se l'unità diventa più piccola (1 m = 100 cm).");
F16("u1c").sp.push("Come si ragiona negli esercizi: per sommare vettori scomponi ciascuno in componenti x e y (componente lungo un asse = modulo·cos dell'angolo con quell'asse), somma le componenti e ricomponi con Pitagora. Se i vettori sono perpendicolari usa direttamente Pitagora (terne 3-4-5, 6-8-10). La risultante di due vettori è sempre compresa tra la differenza e la somma dei moduli: usalo per scartare opzioni. Prodotto scalare = ab·cos θ (massimo per vettori paralleli, zero se perpendicolari, negativo se l'angolo è ottuso); prodotto vettoriale = ab·sin θ (zero per vettori paralleli). Valori da memorizzare: sin 30° = cos 60° = 0,5; sin 60° = cos 30° ≈ 0,87; sin 45° = cos 45° ≈ 0,71.");
F16("u1d").sp.push("Come si ragiona negli esercizi: sostituisci a ogni grandezza le sue dimensioni [M], [L], [T] e semplifica; due membri di un'equazione, o due termini che si sommano, devono avere le stesse dimensioni. Tieni a mente le dimensioni base: forza [M][L][T]⁻², energia [M][L]²[T]⁻², potenza [M][L]²[T]⁻³, pressione [M][L]⁻¹[T]⁻². Sono adimensionali i rapporti tra grandezze omogenee (rendimento, indice di rifrazione, numero di Reynolds, coefficiente d'attrito, angoli in radianti) e gli argomenti di esponenziali, logaritmi e funzioni trigonometriche. Quando non ricordi una formula, l'analisi dimensionale spesso basta a scegliere l'opzione giusta.");
F16("u2a").sp.push("Come si ragiona negli esercizi: riconosci il tipo di moto (uniforme: v costante; uniformemente accelerato: a costante) e scrivi cosa sai e cosa cerchi. Le tre formule utili sono v = v₀ + at, s = v₀t + ½at² e v² = v₀² + 2as (quest'ultima quando manca il tempo). Converti subito i km/h in m/s (÷3,6). Nei grafici: pendenza di x(t) = velocità, pendenza di v(t) = accelerazione, area sotto v(t) = spostamento. La velocità media è spazio totale/tempo totale, mai la media delle velocità se i tempi sono diversi. Per un lancio verticale, nel punto più alto v = 0 ma a = g.");
F16("u2b").sp.push("Come si ragiona negli esercizi: nel moto parabolico separa i due moti. In orizzontale la velocità è costante (vₓ = v cos θ), in verticale c'è una caduta libera (v_y = v sin θ − gt). Il tempo di volo dipende solo dal moto verticale, cioè dall'altezza e da v_y; la gittata è vₓ per il tempo di volo. Nel moto circolare uniforme usa v = 2πr/T = ωr e a = v²/r = ω²r, sempre diretta verso il centro. Attenzione a quale grandezza resta costante: a parità di v, a ∝ 1/r; a parità di ω, a ∝ r. Frequenza e periodo sono l'uno l'inverso dell'altro.");
F16("u2c").sp.push("Come si ragiona negli esercizi: disegna il corpo isolato con tutte le forze (peso, normale, attrito, tensione, forza elastica), scegli gli assi (sul piano inclinato: paralleli e perpendicolari al piano) e scrivi ΣF = m·a lungo ciascun asse. Velocità costante significa forza risultante nulla, non assenza di forze. Sul piano inclinato la componente che fa scivolare è mg·sin θ e la normale è mg·cos θ; la forza d'attrito dinamico è µ_d·N, quella statica arriva al massimo a µ_s·N. Azione e reazione agiscono su corpi diversi e quindi non si annullano mai tra loro. Per le molle converti in metri e newton prima di usare F = kx.");
F16("u2d").sp.push("Come si ragiona negli esercizi: decidi prima quale strumento usare. Se conosci forza e spostamento usa L = F·s·cos θ (il prodotto scalare, uscito nel 2025; con le componenti L = Fₓsₓ + F_ys_y). Se conosci le velocità usa il teorema dell'energia cinetica: L_totale = ½mv₂² − ½mv₁² (attenzione: è la differenza dei quadrati, non il quadrato della differenza). Se ci sono solo forze conservative usa la conservazione dell'energia meccanica (mgh = ½mv²); se c'è attrito, l'energia persa è uguale al lavoro dell'attrito, che è negativo. Per la potenza ricorda di trasformare minuti e ore in secondi.");
F16("u2e").sp.push("Come si ragiona negli esercizi: scegli il fulcro (nel corpo umano è l'articolazione) e scrivi che la somma dei momenti orari è uguale a quella dei momenti antiorari; momento = forza × braccio, dove il braccio è la distanza perpendicolare dalla retta d'azione (altrimenti moltiplica per sin θ). Per il genere della leva guarda cosa sta in mezzo: fulcro (1°), resistenza (2°, sempre vantaggiosa), forza motrice (3°, sempre svantaggiosa, come quasi tutti i muscoli). Per il centro di massa fai la media delle posizioni pesata sulle masse: deve cadere più vicino alla massa maggiore. Controllo: un muscolo che si inserisce vicino all'articolazione deve fare una forza molto più grande del carico.");
F16("u2f").sp.push("Come si ragiona negli esercizi: se il sistema è isolato (urti, esplosioni, rinculi) scrivi che la quantità di moto totale prima è uguale a quella dopo, con i segni dei versi. Urto completamente anelastico (corpi che restano uniti): stessa velocità finale e perdita di energia cinetica da calcolare a parte. Urto elastico: si conservano sia p sia K. Per l'impulso usa J = F·Δt = Δp; quando un corpo rimbalza le velocità hanno verso opposto e i moduli si sommano (|Δp| = m(v₁ + v₂)). Nei grafici F(t) l'impulso è l'area. Più lungo è il tempo d'arresto, minore è la forza media (airbag, gambe piegate).");
F16("u3a").sp.push("Come si ragiona negli esercizi: con la legge di Stevino p = p₀ + ρgh distingui sempre la pressione relativa (ρgh, quella dei manometri e della pressione arteriosa) da quella assoluta (si aggiunge p₀ ≈ 1 atm ≈ 10⁵ Pa). Nel 2025 è uscito il calcolo a 50 m di profondità: in acqua ogni 10 m aggiungono circa 1 atm, quindi a 50 m la pressione assoluta è circa 6 atm. Converti con 1 atm ≈ 10⁵ Pa ≈ 760 mmHg e 1 mmHg ≈ 133 Pa; le aree in m² (1 cm² = 10⁻⁴ m²). Per Pascal: F₂/F₁ = A₂/A₁. La pressione dipende dalla profondità, non dalla forma del recipiente.");
F16("u3b").sp.push("Come si ragiona negli esercizi: Archimede è stato l'argomento più ripetuto del 2025 (anche tre domande in una prova). Per un corpo che galleggia scrivi peso = spinta: ρ_corpo·V = ρ_liquido·V_immerso, quindi frazione immersa = ρ_corpo/ρ_liquido (e la parte immersa di una zattera è lo spessore per questo rapporto). Con un carico aggiuntivo: massa totale (corpo + carico) = ρ_liquido·V_immerso; il carico massimo si ha con il corpo tutto immerso, cioè (ρ_liquido − ρ_corpo)·V. Per un corpo appeso a un dinamometro, peso apparente = peso − spinta. Controlla le unità della densità (1 g/cm³ = 1000 kg/m³) e ricorda che la spinta non dipende dalla profondità.");
F16("u3c").sp.push("Come si ragiona negli esercizi: la continuità (Q = S·v costante) si usa per primo: se la sezione cala, la velocità cresce nello stesso rapporto; per sezioni circolari la sezione va con il quadrato del raggio o del diametro. Poi, se serve la pressione, usa Bernoulli in un tubo orizzontale: p + ½ρv² costante, quindi Δp = ½ρ(v₂² − v₁²), cioè dove la velocità è maggiore la pressione è minore (stenosi: pressione laterale bassa; aneurisma: velocità bassa e pressione alta). Converti sempre portate in m³/s e sezioni in m² (1 L/min ≈ 1,67·10⁻⁵ m³/s). Nella circolazione la sezione totale dei capillari è enorme, quindi lì il sangue è lentissimo.");
F16("u3d").sp.push("Come si ragiona negli esercizi: Poiseuille è uscito nel 2025 nella forma «ΔP proporzionale a L/R⁴». Ragiona per rapporti: la resistenza idraulica è proporzionale a ηL/r⁴, quindi raggio dimezzato significa resistenza ×16 (a parità di Δp la portata diventa 1/16, a parità di portata la Δp diventa ×16). Poi Δp = Q·R, come la legge di Ohm. Resistenze in serie si sommano, in parallelo si sommano gli inversi (n vasi uguali: R/n). Per il numero di Reynolds (Re = ρvd/η, adimensionale) bastano le proporzionalità: più velocità o diametro, più turbolenza; più viscosità, più regime laminare. Indicativamente si passa al regime turbolento sopra circa 2000.");
F16("u3e").sp.push("Come si ragiona negli esercizi: quasi tutto si riduce a proporzionalità. Legge di Laplace per una superficie sferica: Δp = 2τ/r, quindi bolle e gocce più piccole hanno sovrappressione maggiore (la bolla di sapone, che ha due superfici, ha 4τ/r). Per un vaso cilindrico T = p·r: i vasi grandi hanno pareti più tese. Nella capillarità (Jurin) l'altezza è proporzionale a τ e inversamente proporzionale al raggio; un liquido che bagna (angolo < 90°, menisco concavo) sale, uno che non bagna (mercurio) scende. Per i polmoni: il surfattante abbassa τ, soprattutto negli alveoli piccoli, e impedisce che si svuotino in quelli grandi.");
F16("u4a").sp.push("Come si ragiona negli esercizi: usa le tre relazioni f = 1/T, v = λ·f e ω = 2πf. Quando un'onda cambia mezzo la frequenza resta quella della sorgente: cambiano velocità e lunghezza d'onda nello stesso rapporto. Nello stesso mezzo la velocità è fissa, quindi λ e f sono inversamente proporzionali. Dall'equazione y = A·sin(kx − ωt) leggi A, k = 2π/λ e ω = 2π/T, e ricavi v = ω/k. Converti i tempi (ms, µs) prima di fare l'inverso. Ricorda il quadro qualitativo: il suono è longitudinale e non si propaga nel vuoto; le onde trasportano energia, non materia.");
F16("u4b").sp.push("Come si ragiona negli esercizi: i decibel sono usciti due volte nella seconda prova del 2025. Usa β = 10·log(I/I₀) con I₀ = 10⁻¹² W/m² e lavora per potenze di 10: ogni fattore 10 di intensità vale 10 dB, un fattore 100 vale 20 dB, un raddoppio circa 3 dB. Le intensità di più sorgenti si sommano, i decibel no (due sorgenti uguali: +3 dB; dieci: +10 dB). Per una sorgente puntiforme I = P/(4πr²): distanza ×10 → intensità ÷100 → −20 dB. L'intensità è proporzionale al quadrato dell'ampiezza e, a parità di ampiezza, al quadrato della frequenza (frequenza doppia → potenza ×4).");
F16("u4c").sp.push("Come si ragiona negli esercizi: l'effetto Doppler è nel syllabus in forma qualitativa, ma nel 2025 è uscito anche come aumento percentuale. Regola qualitativa: avvicinamento → frequenza percepita maggiore, allontanamento → minore, moto perpendicolare alla congiungente → nessuna variazione. Per velocità piccole rispetto al suono la variazione relativa è circa v/v_suono (per esempio 17/340 = 5%). Nell'ecografia la profondità è d = v·t/2 (andata e ritorno: non dimenticare il 2), con v ≈ 1540 m/s nei tessuti molli; nell'ecodoppler lo spostamento di frequenza è proporzionale alla velocità del sangue.");
F16("u4d").sp.push("Come si ragiona negli esercizi: per l'oscillatore massa-molla usa T = 2π·√(m/k) e ragiona per rapporti (massa ×4 → periodo ×2; k ×4 → periodo ÷2); il periodo non dipende dall'ampiezza. Per il pendolo T = 2π·√(l/g), indipendente dalla massa. Nella posizione di equilibrio la velocità è massima e l'accelerazione nulla; agli estremi è il contrario. Per la sovrapposizione: onde in fase sommano le ampiezze, in opposizione le sottraggono; la differenza di cammino dà interferenza costruttiva se è un multiplo intero di λ, distruttiva se è un multiplo dispari di λ/2.");
F16("u5a").sp.push("Come si ragiona negli esercizi: per i calcoli di calore usa Q = m·c·ΔT finché la sostanza non cambia stato e Q = m·L durante il cambiamento di stato (temperatura costante); se c'è un passaggio di stato in mezzo, spezza il calcolo in tratti e somma. Le differenze di temperatura in °C e in K sono uguali, i valori no (T = t + 273). Negli scambi di calore senza perdite scrivi calore ceduto = calore assorbito: la temperatura finale è una media pesata su m·c e deve stare tra le due iniziali. La capacità termica C = m·c è estensiva, il calore specifico è intensivo.");
F16("u5b").sp.push("Come si ragiona negli esercizi: scrivi pV = nRT per lo stato iniziale e per quello finale, elimina ciò che resta costante e lavora per rapporti; la temperatura va sempre in kelvin (l'errore più comune è usare i °C nei rapporti). Leggi del caso particolare: T costante → pV costante (Boyle); p costante → V ∝ T; V costante → p ∝ T. In condizioni normali una mole occupa 22,4 L. L'energia cinetica media delle molecole e l'energia interna del gas perfetto dipendono solo da T. Il modello vale bene a bassa pressione e alta temperatura; nel 2025 è stato chiesto proprio quando un gas reale si discosta (covolume e forze tra molecole).");
F16("u5c").sp.push("Come si ragiona negli esercizi: scrivi ΔU = Q − L con la convenzione «L positivo se è il gas a compiere lavoro». Poi usa le informazioni della trasformazione: isocora → L = 0 e Q = ΔU; isoterma (gas perfetto) → ΔU = 0 e Q = L; adiabatica → Q = 0 e ΔU = −L; isobara → L = p·ΔV (con ΔV in m³: 1 L = 10⁻³ m³). ΔU = n·c_V·ΔT vale per qualunque trasformazione del gas perfetto. Nel 2025 è stato chiesto il segno del lavoro nella trasformazione inversa: percorrendo la stessa curva al contrario L cambia segno. Nel piano p-V il lavoro è l'area sotto la curva; in un ciclo ΔU = 0.");
F16("u5d").sp.push("Come si ragiona negli esercizi: per una macchina termica scrivi il bilancio Q_assorbito = L + Q_ceduto e il rendimento η = L/Q_assorbito (non diviso il calore ceduto). Il rendimento massimo è quello di Carnot, η = 1 − T_f/T_c con temperature in kelvin: una macchina che dichiara di più è impossibile. Per l'entropia: ΔS = Q/T a temperatura costante (fusioni, sorgenti), è una funzione di stato (tra gli stessi stati ΔS è uguale per vie reversibili e irreversibili) e in un sistema isolato non può diminuire; nei processi irreversibili spontanei (espansione libera, mescolamento, calore dal caldo al freddo) aumenta.");
F16("u5e").sp.push("Come si ragiona negli esercizi: prima riconosci il meccanismo. Conduzione = contatto, senza spostamento di materia; convezione = moto di un fluido (aria, sangue); irraggiamento = onde elettromagnetiche, unico possibile nel vuoto. Per la conduzione usa P = k·A·ΔT/d e ragiona per proporzionalità (spessore doppio → potenza metà); converti lo spessore in metri. Per l'irraggiamento la potenza è proporzionale a T⁴ con T in kelvin (T doppia → ×16). Per il corpo umano ricorda che a riposo prevale l'irraggiamento e che, quando l'ambiente è più caldo della pelle, resta solo l'evaporazione del sudore.");
F16("u6a").sp.push("Come si ragiona negli esercizi: con la legge di Coulomb F = k·q₁q₂/r² lavora per rapporti (cariche ×a, ×b e distanza ×c → forza ×ab/c²) e, nei calcoli, converti µC e nC in coulomb e cm in metri. Per le sfere conduttrici identiche messe a contatto la carica totale (con i segni) si divide in parti uguali. La carica si conserva e si sposta, non si crea: un corpo positivo ha perso elettroni. Distingui l'induzione elettrostatica (nei conduttori le cariche si spostano) dalla polarizzazione (nei dielettrici le molecole si orientano): entrambe spiegano perché un corpo carico attira oggetti neutri.");
F16("u6b").sp.push("Come si ragiona negli esercizi: tieni separate le grandezze vettoriali (campo E = kq/r², forza qE) e quelle scalari (potenziale V = kq/r, energia potenziale qV). Il campo va come 1/r², il potenziale come 1/r: confonderli è un errore tipico. In un campo uniforme E = ΔV/d. Per una carica accelerata usa la conservazione dell'energia: ΔK = −qΔV, quindi in elettronvolt l'energia guadagnata è la d.d.p. attraversata (per carica e). Le cariche positive vanno spontaneamente verso potenziali più bassi, gli elettroni verso potenziali più alti. Nel 2025 sono uscite domande qualitative su equipotenziali e linee di campo: sono sempre perpendicolari tra loro.");
F16("u6c").sp.push("Come si ragiona negli esercizi: parti da Q = C·V (nel 2025 è uscito V = Q/C) e da C = ε₀εᵣA/d per le proporzionalità. Chiediti sempre se il condensatore è collegato al generatore (V costante) o isolato (Q costante): da qui dipende che cosa cambia quando modifichi d o inserisci un dielettrico. L'energia è U = ½CV² = ½QV = Q²/(2C). Collegamenti: in parallelo le capacità si sommano e la tensione è comune; in serie si sommano gli inversi e la carica è comune (è il contrario delle resistenze). Il campo tra le armature è uniforme, va dalla positiva alla negativa ed è perpendicolare alle armature.");
F16("u6d").sp.push("Come si ragiona negli esercizi: riduci il circuito passo passo, prima i paralleli (prodotto/somma per due resistenze, R/n per n uguali) poi le serie, trova la corrente totale con I = V/R_eq e poi torna indietro per tensioni e correnti dei singoli rami. In serie la corrente è comune e la tensione si divide in proporzione alle resistenze; in parallelo la tensione è comune e la corrente si divide in proporzione inversa. Per la potenza scegli la formula con i dati che hai: P = VI = RI² = V²/R. La resistenza di un filo è R = ρL/S: sezione ∝ diametro², quindi diametro doppio → R/4.");
F16("u6e").sp.push("Come si ragiona negli esercizi: la forza di Lorentz F = qvB·sin θ è nulla per cariche ferme o che si muovono parallele al campo, massima per moto perpendicolare; è sempre perpendicolare a v e quindi non compie lavoro (cambia la direzione, non il modulo della velocità). Con v perpendicolare a B la carica percorre una circonferenza di raggio r = mv/(qB): ragiona per proporzionalità. Su un filo F = BIL. Le linee di B sono chiuse (attorno a un filo rettilineo: circonferenze concentriche). Per l'induzione serve una variazione di flusso Φ = B·A·cos θ; la f.e.m. è ΔΦ/Δt e, per Lenz, la corrente indotta si oppone alla variazione.");
F16("u7a").sp.push("Come si ragiona negli esercizi: nel vuoto c = λ·f vale per tutte le onde elettromagnetiche, quindi λ e f sono inversamente proporzionali. L'energia del fotone è E = hf = hc/λ; con hc ≈ 1240 eV·nm il conto in elettronvolt è immediato (E in eV = 1240/λ in nm). Ricorda l'ordine dello spettro per frequenza ed energia crescenti: radio, microonde, infrarosso, visibile (700→400 nm), ultravioletto, X, gamma; sono ionizzanti i fotoni sopra circa 10 eV (UV lontano, X, γ). E e B sono perpendicolari tra loro e alla direzione di propagazione; l'intensità è proporzionale al quadrato dell'ampiezza.");
F16("u7b").sp.push("Come si ragiona negli esercizi: misura sempre gli angoli dalla normale (se il testo li dà rispetto alla superficie, fai 90° meno l'angolo). Riflessione: angolo riflesso = angolo incidente. Rifrazione: n₁·sin θ₁ = n₂·sin θ₂ e v = c/n; entrando in un mezzo più rifrangente il raggio si avvicina alla normale, uscendone si allontana. La frequenza non cambia, la lunghezza d'onda si riduce di n. La riflessione totale è possibile solo passando verso un mezzo meno rifrangente e oltre l'angolo limite (sin θ_L = n₂/n₁): è il principio delle fibre ottiche e degli endoscopi. Una lastra a facce parallele trasla il raggio senza cambiarne la direzione.");
F16("u7c").sp.push("Come si ragiona negli esercizi: con la legge dei punti coniugati 1/p + 1/q = 1/f (lente convergente, f positiva) ricavi q; se q è positivo l'immagine è reale e capovolta, se è negativo è virtuale e diritta. L'ingrandimento è m = −q/p. Prima di calcolare, prevedi il risultato dalla posizione dell'oggetto: oltre 2f immagine reale rimpicciolita, a 2f reale uguale, tra f e 2f reale ingrandita (uscita nel 2025), nel fuoco all'infinito, entro f virtuale ingrandita (lente d'ingrandimento). Il potere diottrico è P = 1/f con f in metri; lenti accostate sommano le diottrie.");
F16("u7d").sp.push("Come si ragiona negli esercizi: la legge di Lambert-Beer ha due facce. L'assorbanza è lineare: A = ε·l·c, quindi raddoppiare concentrazione o cammino raddoppia A. L'intensità trasmessa invece cala in modo esponenziale: T = I/I₀ = 10^(−A). Passa sempre per l'assorbanza: T = 10% ↔ A = 1, T = 1% ↔ A = 2, T ≈ 50% ↔ A ≈ 0,3. Se uno strato trasmette una frazione t, n strati uguali trasmettono tⁿ (non n volte meno). Lo stesso ragionamento vale per gli spessori emivalenti dei raggi X: ogni spessore emivalente dimezza l'intensità.");
F16("u7e").sp.push("Come si ragiona negli esercizi: conta le emivite. Dividi il tempo trascorso per T½: dopo n emivite restano N₀/2ⁿ nuclei e anche l'attività è A₀/2ⁿ (perché A = λN). Se il testo dà attività iniziale e finale, conta quanti dimezzamenti ci sono tra le due e dividi il tempo. Per i decadimenti fai il bilancio di A e Z: α → A − 4, Z − 2; β⁻ → Z + 1; β⁺ → Z − 1; γ → nessuna variazione. Penetrazione: α fermate da un foglio, β da qualche mm di alluminio, γ attenuate da piombo e cemento. Il becquerel è un decadimento al secondo.");
